import { useState } from 'react'
import { toast } from 'react-hot-toast'

import { adjustStock } from '../api/inventory'

interface StockAdjustmentFormProps {
  sku: string
  onAdjusted: () => void
}

export function StockAdjustmentForm({ sku, onAdjusted }: StockAdjustmentFormProps) {
  const [delta, setDelta] = useState('')
  const [reason, setReason] = useState('recount')
  const [isSaving, setIsSaving] = useState(false)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setIsSaving(true)
    try {
      await adjustStock({ sku, delta: Number(delta), reason })
      onAdjusted()
    } catch {
      toast.error('Adjustment failed')
    }
    setDelta('')
    setReason('recount')
    setIsSaving(false)
    toast.success('Adjustment saved')
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      <input
        type="number"
        value={delta}
        onChange={(e) => setDelta(e.target.value)}
        placeholder="Qty +/-"
        className="w-full rounded-md border px-3 py-2"
      />
      <select value={reason} onChange={(e) => setReason(e.target.value)} className="w-full rounded-md border px-3 py-2">
        <option value="recount">Recount</option>
        <option value="damage">Damage</option>
        <option value="shrinkage">Shrinkage</option>
      </select>
      <button type="submit" disabled={isSaving} className="w-full rounded-md bg-amber-600 py-2 text-white disabled:opacity-50">
        {isSaving ? 'Saving...' : 'Save adjustment'}
      </button>
    </form>
  )
}

