import { useState } from 'react'

import { QuoteStepDriver } from './QuoteStepDriver'
import { QuoteStepVehicle } from './QuoteStepVehicle'
import { QuoteStepCoverage } from './QuoteStepCoverage'
import { submitQuote } from '../api/quotes'
import { validateQuote } from '../lib/quoteValidation'
import type { QuoteDraft, StepErrors } from '../types'

const STEPS = [QuoteStepDriver, QuoteStepVehicle, QuoteStepCoverage]

export function QuoteWizard() {
  const [step, setStep] = useState(0)
  const [draft, setDraft] = useState<QuoteDraft>({ driver: {}, vehicle: {}, coverage: {} })
  const [errors, setErrors] = useState<StepErrors>({})

  const StepComponent = STEPS[step]
  const isLast = step === STEPS.length - 1

  function handleNext() {
    if (isLast) {
      const allErrors = validateQuote(draft)
      if (Object.keys(allErrors).length > 0) {
        setErrors(allErrors)
        return
      }
      submitQuote(draft)
      return
    }
    setStep((s) => s + 1)
  }

  return (
    <div className="mx-auto max-w-xl p-6">
      <StepComponent draft={draft} onChange={setDraft} errors={errors} />
      <div className="mt-6 flex justify-between">
        <button onClick={() => setStep((s) => Math.max(s - 1, 0))} disabled={step === 0} className="rounded-lg border px-4 py-2 disabled:opacity-50">
          Back
        </button>
        <button onClick={handleNext} className="rounded-lg bg-blue-600 px-4 py-2 text-white hover:bg-blue-700">
          {isLast ? 'Get quote' : 'Next'}
        </button>
      </div>
    </div>
  )
}

