import { useState } from 'react'

interface GearRow {
  gear: string
  startDate: string
}

export function RentalLineItems({ onRowsChange }: { onRowsChange: (rows: GearRow[]) => void }) {
  const [rows, setRows] = useState<GearRow[]>([{ gear: '', startDate: '' }])

  function update(i: number, patch: Partial<GearRow>) {
    const next = rows.map((r, idx) => (idx === i ? { ...r, ...patch } : r))
    setRows(next)
    onRowsChange(next)
  }

  function addRow() {
    setRows([...rows, { gear: '', startDate: '' }])
  }

  function removeRow(i: number) {
    const next = rows.filter((_, idx) => idx !== i)
    setRows(next)
    onRowsChange(next)
  }

  return (
    <fieldset className="space-y-3">
      {rows.map((row, i) => (
        <div key={i} className="flex items-end gap-3 rounded-lg border p-3">
          <input
            value={row.gear}
            onChange={e => update(i, { gear: e.target.value })}
            placeholder="Equipment name"
            className="w-56 rounded-md border px-2 py-1.5"
          />
          <input
            type="date"
            defaultValue={row.startDate}
            onChange={e => update(i, { startDate: e.target.value })}
            className="rounded-md border px-2 py-1.5"
          />
          <button type="button" onClick={() => removeRow(i)} className="text-sm font-medium text-red-600">Remove</button>
        </div>
      ))}
      <button type="button" onClick={addRow} className="rounded-md bg-slate-900 px-3 py-1.5 text-sm text-white">Add equipment</button>
    </fieldset>
  )
}

