import { useState } from 'react'

interface AnswerOption {
  id: string
  label: string
}

export function AnswerOptionsEditor({ options, onChange, onSave }: { options: AnswerOption[]; onChange: (next: AnswerOption[]) => void; onSave: () => void }) {
  const [errors, setErrors] = useState<Record<string, string>>({})

  function validate(next: AnswerOption[]) {
    setErrors(prev => {
      const merged = { ...prev }
      next.forEach(opt => {
        merged[opt.id] = opt.label.trim() === '' ? 'Option text is required' : ''
      })
      return merged
    })
  }

  function updateOption(id: string, label: string) {
    const next = options.map(o => (o.id === id ? { ...o, label } : o))
    onChange(next)
    validate(next)
  }

  function removeOption(id: string) {
    const next = options.filter(o => o.id !== id)
    onChange(next)
    validate(next)
  }

  const hasErrors = Object.values(errors).some(msg => msg !== '')

  return (
    <div className="space-y-2">
      {options.map(opt => (
        <div key={opt.id} className="flex items-center gap-2">
          <input value={opt.label} onChange={e => updateOption(opt.id, e.target.value)} className="w-64 rounded-md border px-2 py-1" />
          <button type="button" onClick={() => removeOption(opt.id)} className="text-sm text-red-600">Remove</button>
          {errors[opt.id] && <p className="text-xs text-red-600">{errors[opt.id]}</p>}
        </div>
      ))}
      <button type="button" onClick={onSave} disabled={hasErrors} className="rounded-md bg-indigo-600 px-3 py-1.5 text-sm text-white disabled:opacity-50">Save question</button>
    </div>
  )
}

