import { useEffect, useState } from 'react'
import { searchSpecies, type SpeciesMatch } from '../lib/speciesApi'

interface SpeciesSearchState {
  matches: SpeciesMatch[]
  loading: boolean
  error: string | null
}

export function useSpeciesSearch(query: string): SpeciesSearchState {
  const [matches, setMatches] = useState<SpeciesMatch[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (query.trim().length < 2) {
      setMatches([])
      setLoading(false)
      return
    }
    setLoading(true)
    setError(null)
    searchSpecies(query)
      .then((data) => {
        setMatches(data)
        setLoading(false)
      })
      .catch(() => {
        setError('Could not load species matches')
        setLoading(false)
      })
  }, [query])

  return { matches, loading, error }
}

