  id: string
  commonName: string
  scientificName: string
}

export async function searchSpecies(
  query: string,
  signal?: AbortSignal,
): Promise<SpeciesMatch[]> {
  const res = await fetch(`/api/species?q=${encodeURIComponent(query)}`, { signal })
  if (!res.ok) {
    throw new Error(`species search failed with ${res.status}`)
  }
  return res.json()
}

