import { useCallback, useEffect, useState } from 'react'
import { fetchLiftStatuses, type LiftStatus } from './liftApi'

const POLL_MS = 20000

interface LiftStatusesState {
  lifts: LiftStatus[]
  error: string | null
  refresh: () => void
}

export function useLiftStatuses(): LiftStatusesState {
  const [lifts, setLifts] = useState<LiftStatus[]>([])
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    try {
      const data = await fetchLiftStatuses()
      setLifts(data)
      setError(null)
    } catch {
      setError('Lift status update failed, showing last known data')
    }
  }, [])

  useEffect(() => {
    load()
    const timer = setInterval(load, POLL_MS)
    return () => clearInterval(timer)
  }, [load])

  return { lifts, error, refresh: load }
}

