import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { act, renderHook } from '@testing-library/react'
import { useLiftStatuses } from '../useLiftStatuses'
import * as liftApi from '../liftApi'

const openLift = { id: 'eagle-express', name: 'Eagle Express', status: 'open' as const }
const holdLift = { id: 'eagle-express', name: 'Eagle Express', status: 'hold' as const }

describe('useLiftStatuses', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.restoreAllMocks()
    vi.useRealTimers()
  })

  it('loads statuses on mount', async () => {
    vi.spyOn(liftApi, 'fetchLiftStatuses').mockResolvedValue([openLift])
    const { result } = renderHook(() => useLiftStatuses())
    await act(() => vi.runOnlyPendingTimersAsync())
    expect(result.current.lifts).toEqual([openLift])
  })

  it('manual refresh result survives a slower in-flight poll', async () => {
    const spy = vi.spyOn(liftApi, 'fetchLiftStatuses')
    let resolvePoll: (lifts: liftApi.LiftStatus[]) => void = () => {}
    spy.mockResolvedValueOnce([holdLift])
    const { result } = renderHook(() => useLiftStatuses())
    await act(() => vi.runOnlyPendingTimersAsync())

    spy.mockImplementationOnce(() => new Promise((res) => { resolvePoll = res }))
    await act(() => vi.advanceTimersByTimeAsync(20000))

    spy.mockResolvedValueOnce([openLift])
    await act(async () => { result.current.refresh() })

    await act(async () => { resolvePoll([holdLift]) })
    expect(result.current.lifts[0].status).toBe('open')
  })

  it('unmount stops the poll timer', async () => {
    const spy = vi.spyOn(liftApi, 'fetchLiftStatuses').mockResolvedValue([openLift])
    const { unmount } = renderHook(() => useLiftStatuses())
    await act(() => vi.runOnlyPendingTimersAsync())
    unmount()
    const calls = spy.mock.calls.length
    await act(() => vi.advanceTimersByTimeAsync(60000))
    expect(spy.mock.calls.length).toBe(calls)
  })
})

