import { fetchRecordPage, type RecordListing } from './crateApi'

interface RecordPageState {
  records: RecordListing[]
  loading: boolean
  error: string | null
}

export function useRecordPage(page: number): RecordPageState {
  const [records, setRecords] = useState<RecordListing[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let ignore = false
    async function run() {
      setLoading(true)
      setError(null)
      try {
        const data = await fetchRecordPage(page)
        setRecords(data)
      } catch {
        setError('Could not load this page of listings')
      } finally {
        setLoading(false)
      }
    }
    run()
  }, [page])

  return { records, loading, error }
}

