import type { Plot, WateringDay } from './types'

export interface PlotsState {
  plots: Plot[]
  selectedPlotId: string
  wateringDay: WateringDay
}

export const initialPlotsState: PlotsState = {
  plots: [],
  selectedPlotId: '',
  wateringDay: 'saturday',
}

export type PlotsAction =
  | { type: 'plots_loaded'; plots: Plot[] }
  | { type: 'select_plot'; plotId: string }
  | { type: 'clear_selection' }
  | { type: 'set_watering_day'; day: WateringDay }

export function plotsReducer(state: PlotsState, action: PlotsAction): PlotsState {
  switch (action.type) {
    case 'plots_loaded':
      return { ...state, plots: action.plots }
    case 'select_plot':
      return { ...state, selectedPlotId: action.plotId }
    case 'clear_selection':
      return { ...state, selectedPlotId: '' }
    case 'set_watering_day':
      return { ...state, wateringDay: action.day }
  }
}

import { usePlotsState } from '../../state/PlotsProvider'
import { WateringLog } from './WateringLog'

interface PlotDetailPanelProps {
  onCopyShareLink: (plotId: string) => void
}

export function PlotDetailPanel({ onCopyShareLink }: PlotDetailPanelProps) {
  const state = usePlotsState()
  const plot = state.plots.find((p) => p.id === state.selectedPlotId)

  if (!state.selectedPlotId) {
    return (
      <p className="p-6 text-base text-zinc-500">
        Select a plot on the map to see its details.
      </p>
    )
  }

  if (!plot) {
    return (
      <p className="p-6 text-base text-zinc-500">
        Plot {state.selectedPlotId} is no longer assigned. Pick another plot.
      </p>
    )
  }

  return (
    <section className="flex flex-col gap-4 p-6">
      <h2 className="text-xl font-semibold text-zinc-900">
        Plot {plot.label} - {plot.holderName}
      </h2>
      <p className="text-base text-zinc-600">
        Bed size {plot.bedSizeSqFt} sq ft, watering on {state.wateringDay}.
      </p>
      <button
        type="button"
        onClick={() => onCopyShareLink(state.selectedPlotId)}
        className="self-start rounded-md bg-emerald-700 px-4 py-2 text-base font-medium text-white hover:bg-emerald-800 focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 active:scale-[0.98]"
      >
        Copy share link
      </button>
      <WateringLog plotId={plot.id} day={state.wateringDay} />
    </section>
  )
}

