  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    fetch('/api/sailings')
      .then((res) => {
        if (!res.ok) throw new Error('Sailings request failed: ' + res.status)
        return res.json() as Promise<Sailing[]>
      })
      .then((data) => {
        if (!cancelled) setSailings(data)
      })
      .catch((e) => {
        if (!cancelled) setError((e as Error).message)
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [setSailings])

