import { create } from 'zustand'
import type { Sailing } from '../types/sailing'

type LoadStatus = 'idle' | 'loading' | 'loaded' | 'error'

interface SailingsState {
  sailings: Sailing[]
  status: LoadStatus
  error: string | null
  loadSailings: () => Promise<void>
}

export const useSailingsStore = create<SailingsState>((set, get) => ({
  sailings: [],
  status: 'idle',
  error: null,
  loadSailings: async () => {
    if (get().status === 'loading') return
    set({ status: 'loading', error: null })
    try {
      const res = await fetch('/api/sailings')
      if (!res.ok) {
        throw new Error('Sailings request failed: ' + res.status)
      }
      const data = (await res.json()) as Sailing[]
      set({ sailings: data, status: 'loaded' })
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : 'Unexpected error loading sailings'
      set({ status: 'error', error: message })
    }
  },
}))

import { useEffect } from 'react'
import { useSailingsStore } from '../stores/useSailingsStore'
import { SailingRow } from './SailingRow'

export function DepartureBoard() {
  const sailings = useSailingsStore((s) => s.sailings)
  const status = useSailingsStore((s) => s.status)
  const error = useSailingsStore((s) => s.error)
  const loadSailings = useSailingsStore((s) => s.loadSailings)

  useEffect(() => {
    if (useSailingsStore.getState().status === 'idle') {
      void loadSailings()
    }
  }, [loadSailings])

  if (status === 'idle' || status === 'loading') {
    return <div className="h-64 animate-pulse rounded-lg bg-zinc-100" aria-hidden="true" />
  }

  if (status === 'error') {
    return (
      <div role="alert" className="rounded-lg border border-red-200 bg-red-50 p-4">
        <p className="text-base text-red-800">Could not load departures: {error}</p>
        <button
          type="button"
          onClick={() => void loadSailings()}
          className="mt-2 rounded-md border border-red-300 px-4 py-2 text-base font-medium text-red-800 hover:bg-red-100 focus-visible:ring-2 focus-visible:ring-red-500 focus-visible:ring-offset-2 active:scale-[0.98]"
        >
          Retry
        </button>
      </div>
    )
  }

  if (sailings.length === 0) {
    return <p className="p-4 text-base text-zinc-600">No sailings scheduled today. Check the seasonal timetable.</p>
  }

  return (
    <table className="w-full">
      <tbody>
        {sailings.map((s) => (
          <SailingRow key={s.id} sailing={s} />
        ))}
      </tbody>
    </table>
  )
}

