import { createContext, useContext, useMemo, useReducer } from 'react'
import type { ReactNode } from 'react'
import type { DeferralReason, Donor } from '../types/donor'

export interface CheckInState {
  donors: Donor[]
  search: string
  deferred: Record<string, DeferralReason>
}

export interface CheckInAction {
  type: string
  payload?: any
}

const initialState: CheckInState = {
  donors: [],
  search: '',
  deferred: {},
}

function checkInReducer(state: CheckInState, action: CheckInAction): CheckInState {
  switch (action.type) {
    case 'donors_loaded':
      return { ...state, donors: action.payload as Donor[] }
    case 'search_changed':
      return { ...state, search: action.payload as string }
    case 'donor_deferred': {
      const { donorId, reason } = action.payload as { donorId: string; reason: DeferralReason }
      return { ...state, deferred: { ...state.deferred, [donorId]: reason } }
    }
    default:
      return state
  }
}

interface CheckInContextValue {
  state: CheckInState
  dispatch: (action: CheckInAction) => void
}

const CheckInContext = createContext<CheckInContextValue | null>(null)

export function DonorCheckInProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(checkInReducer, initialState)
  const value = useMemo(() => ({ state, dispatch }), [state])
  return <CheckInContext.Provider value={value}>{children}</CheckInContext.Provider>
}

export function useCheckIn(): CheckInContextValue {
  const ctx = useContext(CheckInContext)
  if (ctx === null) {
    throw new Error('useCheckIn must be used inside DonorCheckInProvider')
  }
  return ctx
}

