import { createContext, useContext, useReducer } from 'react'
import type { Dispatch, ReactNode } from 'react'
import type { DeferralReason, Donor } from '../types/donor'

export interface CheckInState {
  donors: Donor[]
  search: string
  deferred: Record<string, DeferralReason>
}

export type CheckInAction =
  | { type: 'donors_loaded'; donors: Donor[] }
  | { type: 'search_changed'; search: string }
  | { type: 'donor_deferred'; donorId: string; reason: DeferralReason }

const initialState: CheckInState = {
  donors: [],
  search: '',
  deferred: {},
}

function checkInReducer(state: CheckInState, action: CheckInAction): CheckInState {
  switch (action.type) {
    case 'donors_loaded':
      return { ...state, donors: action.donors }
    case 'search_changed':
      return { ...state, search: action.search }
    case 'donor_deferred':
      return { ...state, deferred: { ...state.deferred, [action.donorId]: action.reason } }
  }
}

const CheckInStateContext = createContext<CheckInState | null>(null)
const CheckInDispatchContext = createContext<Dispatch<CheckInAction> | null>(null)

export function DonorCheckInProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(checkInReducer, initialState)
  return (
    <CheckInStateContext.Provider value={state}>
      <CheckInDispatchContext.Provider value={dispatch}>{children}</CheckInDispatchContext.Provider>
    </CheckInStateContext.Provider>
  )
}

export function useCheckInState(): CheckInState {
  const ctx = useContext(CheckInStateContext)
  if (ctx === null) {
    throw new Error('useCheckInState must be used inside DonorCheckInProvider')
  }
  return ctx
}

export function useCheckInDispatch(): Dispatch<CheckInAction> {
  const ctx = useContext(CheckInDispatchContext)
  if (ctx === null) {
    throw new Error('useCheckInDispatch must be used inside DonorCheckInProvider')
  }
  return ctx
}

import { useCheckInDispatch, useCheckInState } from '../context/DonorCheckInContext'

export function DonorQueue() {
  const state = useCheckInState()
  const dispatch = useCheckInDispatch()
  const visible = state.donors.filter((d) =>
    d.fullName.toLowerCase().includes(state.search.toLowerCase()),
