          value={state.search}
          onChange={(e) => dispatch({ type: 'search_changed', search: e.target.value })}
          className="rounded-md border border-zinc-300 px-3 py-2 text-base focus-visible:ring-2 focus-visible:ring-rose-600 focus-visible:ring-offset-2"
        />
      </div>
      <ul className="flex flex-col gap-2">
