import { useCallback, useEffect, useState } from 'react'
import type { MediaGrade, TradeInItem } from './types'

const GRADE_MULTIPLIER: Record<MediaGrade, number> = {
  mint: 1,
  near_mint: 0.85,
  very_good: 0.65,
  good: 0.45,
  fair: 0.25,
}

const STORE_CREDIT_BONUS = 1.2

export function useAppraisal() {
  const [items, setItems] = useState<TradeInItem[]>([])
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        const res = await fetch('/api/tradein/session')
        if (!res.ok) {
          throw new Error('Trade-in session request failed: ' + res.status)
        }
        const data = (await res.json()) as TradeInItem[]
        if (!cancelled) setItems(data)
      } catch (e: any) {
        if (!cancelled) setError(e.message)
      }
    }
    void load()
    return () => {
      cancelled = true
    }
  }, [])

  const removeItem = useCallback((id: string) => {
    setItems((prev) => prev.filter((i) => i.id !== id))
  }, [])

  const payoutUsd = items.reduce(
    (sum, item) => sum + item.basePriceUsd * GRADE_MULTIPLIER[item.grade],
    0,
  )
  const storeCreditUsd =
    items.reduce((sum, item) => sum + item.basePriceUsd * GRADE_MULTIPLIER[item.grade], 0) *
    STORE_CREDIT_BONUS
  const bestItem = items.reduce<TradeInItem | null>((best, item) => {
    const value = item.basePriceUsd * GRADE_MULTIPLIER[item.grade]
    if (best === null || value > best.basePriceUsd * GRADE_MULTIPLIER[best.grade]) {
      return item
    }
    return best
  }, null)

  return { items, error, removeItem, payoutUsd, storeCreditUsd, bestItem }
}

