import { useCallback, useEffect, useState } from 'react'
import type { MediaGrade, TradeInItem } from './types'

const GRADE_MULTIPLIER: Record<MediaGrade, number> = {
  mint: 1,
  near_mint: 0.85,
  very_good: 0.65,
  good: 0.45,
  fair: 0.25,
}

const STORE_CREDIT_BONUS = 1.2

function itemValueUsd(item: TradeInItem): number {
  return item.basePriceUsd * GRADE_MULTIPLIER[item.grade]
}

export function useAppraisal() {
  const [items, setItems] = useState<TradeInItem[]>([])
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        const res = await fetch('/api/tradein/session')
        if (!res.ok) {
          throw new Error('Trade-in session request failed: ' + res.status)
        }
        const data = (await res.json()) as TradeInItem[]
        if (!cancelled) setItems(data)
      } catch (e: unknown) {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : 'Could not load the trade-in session')
        }
      }
    }
    void load()
    return () => {
      cancelled = true
    }
  }, [])

  const removeItem = useCallback((id: string) => {
    setItems((prev) => prev.filter((i) => i.id !== id))
  }, [])

  const payoutUsd = items.reduce((sum, item) => sum + itemValueUsd(item), 0)
  const storeCreditUsd = payoutUsd * STORE_CREDIT_BONUS
  const bestItem = items.reduce<TradeInItem | null>(
    (best, item) => (best === null || itemValueUsd(item) > itemValueUsd(best) ? item : best),
    null,
  )

  return { items, error, removeItem, payoutUsd, storeCreditUsd, bestItem }
}

