import { KeyboardEvent, useRef, useState } from 'react'

const TABS = ['Parameters', 'Livestock', 'Dosing', 'Alerts'] as const

interface TankTabsProps {
  onTabChange: (tab: string) => void
}

export function TankTabs({ onTabChange }: TankTabsProps) {
  const [activeIndex, setActiveIndex] = useState(0)
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([])

  function focusTab(index: number) {
    setActiveIndex(index)
    tabRefs.current[index]?.focus()
    onTabChange(TABS[index])
  }

  function handleKeyDown(event: KeyboardEvent, index: number) {
    if (event.key === 'ArrowRight') {
      event.preventDefault()
      const next = index === TABS.length ? 0 : index + 1
      focusTab(next)
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      const prev = index === 0 ? TABS.length : index - 1
      focusTab(prev)
    }
  }

  return (
    <div role="tablist" aria-label="Tank sections" className="flex gap-2">
      {TABS.map((tab, index) => (
        <button
          key={tab}
          ref={(el) => (tabRefs.current[index] = el)}
          role="tab"
          aria-selected={index === activeIndex}
          tabIndex={index === activeIndex ? 0 : -1}
          onClick={() => focusTab(index)}
          onKeyDown={(event) => handleKeyDown(event, index)}
          className="rounded-md px-4 py-2 text-sm font-medium text-slate-700 focus-visible:ring-2 focus-visible:ring-teal-500 focus-visible:ring-offset-2"
        >
          {tab}
        </button>
      ))}
    </div>
  )
}

