import { describe, expect, it } from 'vitest'

import { stopSlaState } from './sla'

const stop = { id: 'st-4471', consignee: 'Halvorsen Tile Supply', windowStart: '09:00', windowEnd: '11:00' }

describe('stopSlaState', () => {
  it('treats a stop exactly at the SLA allowance as breached', () => {
    expect(stopSlaState({ ...stop, minutesLate: 15, slaMinutes: 15 })).toBe('breached')
  })

  it('leaves a stop inside the allowance on time', () => {
    expect(stopSlaState({ ...stop, minutesLate: 14, slaMinutes: 15 })).toBe('on-time')
  })

  it('treats an early stop as on time', () => {
    expect(stopSlaState({ ...stop, minutesLate: 0, slaMinutes: 15 })).toBe('on-time')
  })
})

