  palletId: string
  dockDoor: string
  reason: 'missing-label' | 'weight-mismatch' | 'wrong-door'
  scannedAt: string
}

export async function fetchScanExceptions(dockDoor: string, signal?: AbortSignal): Promise<ScanException[]> {
  const response = await fetch('/api/crossdock/exceptions?door=' + encodeURIComponent(dockDoor), { signal })
  if (!response.ok) throw new Error('Scan exception feed is unavailable')
