import { useEffect, useState } from 'react'

import { fetchScanExceptions, type ScanException } from './api'

interface ScanExceptionsState {
  exceptions: ScanException[]
  status: 'loading' | 'ready' | 'error'
}

export function useScanExceptions(dockDoor: string) {
  const [state, setState] = useState<ScanExceptionsState>({ exceptions: [], status: 'loading' })
  const [attempt, setAttempt] = useState(0)

  useEffect(() => {
    const controller = new AbortController()
    setState({ exceptions: [], status: 'loading' })

    fetchScanExceptions(dockDoor, controller.signal)
      .then((exceptions) => {
        if (controller.signal.aborted) return
        setState({ exceptions, status: 'ready' })
      })
      .catch(() => {
        if (controller.signal.aborted) return
        setState({ exceptions: [], status: 'error' })
      })

    return () => controller.abort()
  }, [dockDoor, attempt])

  return { ...state, retry: () => setAttempt((current) => current + 1) }
}

import type { ScanException } from './api'
import { useScanExceptions } from './useScanExceptions'

interface ScanExceptionListProps {
  dockDoor: string
}

const REASON_LABEL: Record<ScanException['reason'], string> = {
  'missing-label': 'Label unreadable',
  'weight-mismatch': 'Weight off manifest',
  'wrong-door': 'Staged at wrong door',
}

const actionClass =
  'rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-900 transition-colors hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2 active:scale-[0.98] motion-reduce:transition-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900'

export function ScanExceptionList({ dockDoor }: ScanExceptionListProps) {
  const { exceptions, status, retry } = useScanExceptions(dockDoor)

  if (status === 'loading') {
    return (
      <ul aria-busy="true" className="flex flex-col gap-2">
        {['first', 'second', 'third'].map((row) => (
          <li key={row} className="h-16 animate-pulse rounded-lg bg-zinc-100 motion-reduce:animate-none dark:bg-zinc-900" />
        ))}
      </ul>
    )
  }

  if (status === 'error') {
    return (
      <div role="alert" className="flex flex-col items-start gap-4 rounded-lg border border-red-300 p-6 dark:border-red-900">
        <p className="text-base text-zinc-900 dark:text-zinc-100">
          The scan exception feed for door {dockDoor} did not respond.
        </p>
        <button type="button" onClick={retry} className={actionClass}>Try again</button>
      </div>
    )
  }

  if (exceptions.length === 0) {
    return (
      <div className="flex flex-col items-start gap-4 rounded-lg border border-zinc-200 p-6 dark:border-zinc-800">
        <p className="text-base text-zinc-700 dark:text-zinc-300">
          No scan exceptions on door {dockDoor} for this shift.
        </p>
        <button type="button" onClick={retry} className={actionClass}>Check again</button>
      </div>
    )
  }

  return (
    <ul className="flex flex-col gap-2">
      {exceptions.map((exception) => (
        <li
          key={exception.id}
          className="flex items-center justify-between gap-4 rounded-lg border border-zinc-200 px-4 py-3 dark:border-zinc-800"
        >
          <span className="min-w-0">
            <span className="block truncate text-base font-medium tabular-nums text-zinc-900 dark:text-zinc-100">
              {exception.palletId}
            </span>
            <span className="block text-sm text-zinc-600 dark:text-zinc-400">{REASON_LABEL[exception.reason]}</span>
          </span>
          <span className="shrink-0 text-sm tabular-nums text-zinc-600 dark:text-zinc-400">
            Door {exception.dockDoor}
          </span>
        </li>
      ))}
    </ul>
  )
}

import { renderHook, waitFor } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { fetchScanExceptions } from './api'
import { useScanExceptions } from './useScanExceptions'

vi.mock('./api', () => ({ fetchScanExceptions: vi.fn() }))

const doorNine = [
  { id: 'ex-3301', palletId: 'PLT-77412', dockDoor: 'D9', reason: 'weight-mismatch', scannedAt: '2026-07-27T08:14:00Z' },
]
const doorTwo = [
  { id: 'ex-3318', palletId: 'PLT-77590', dockDoor: 'D2', reason: 'missing-label', scannedAt: '2026-07-27T08:41:00Z' },
]

describe('useScanExceptions', () => {
  it('ignores a slow response for a door the picker has already left', async () => {
    vi.mocked(fetchScanExceptions).mockImplementation(
      (dockDoor, signal) =>
        new Promise((resolve, reject) => {
          const timer = setTimeout(() => resolve(dockDoor === 'D9' ? doorNine : doorTwo), dockDoor === 'D9' ? 60 : 5)
          signal?.addEventListener('abort', () => {
            clearTimeout(timer)
            reject(new DOMException('Aborted', 'AbortError'))
          })
        }),
    )

    const { result, rerender } = renderHook(({ dockDoor }) => useScanExceptions(dockDoor), {
      initialProps: { dockDoor: 'D9' },
    })
    rerender({ dockDoor: 'D2' })

    await waitFor(() => expect(result.current.status).toBe('ready'))
    expect(result.current.exceptions).toEqual(doorTwo)

    await new Promise((resolve) => setTimeout(resolve, 90))
    expect(result.current.exceptions).toEqual(doorTwo)
  })

  it('reports a failed feed instead of showing an empty door', async () => {
    vi.mocked(fetchScanExceptions).mockRejectedValue(new Error('Scan exception feed is unavailable'))

    const { result } = renderHook(() => useScanExceptions('D4'))

    await waitFor(() => expect(result.current.status).toBe('error'))
    expect(result.current.exceptions).toEqual([])
  })
})

