import { useState } from 'react'

import { sortAppointments, type DrayageAppointment, type SortKey } from './appointments'

interface DrayageAppointmentTableProps {
  appointments: DrayageAppointment[]
}

const COLUMNS: { key: SortKey; label: string }[] = [
  { key: 'containerNo', label: 'Container' },
  { key: 'terminal', label: 'Terminal' },
  { key: 'windowStart', label: 'Window opens' },
]

const STATUS_LABEL: Record<DrayageAppointment['status'], string> = {
  booked: 'Booked',
  arrived: 'Truck arrived',
  missed: 'Window missed',
}

function formatWindow(isoTime: string) {
  return new Date(isoTime).toLocaleString('en-US', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })
}

export function DrayageAppointmentTable({ appointments }: DrayageAppointmentTableProps) {
  const [sortKey, setSortKey] = useState<SortKey>('windowStart')

  if (appointments.length === 0) {
    return (
      <p className="rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        No drayage appointments booked for this terminal today. Book a window to reserve a slot.
      </p>
    )
  }

  const rows = sortAppointments(appointments, sortKey)

  return (
    <table className="w-full border-collapse text-left">
      <caption className="sr-only">Drayage appointments, sorted by {sortKey}</caption>
      <thead>
        <tr className="border-b border-zinc-200 dark:border-zinc-800">
          {COLUMNS.map((column) => (
            <th
              key={column.key}
              scope="col"
              aria-sort={sortKey === column.key ? 'ascending' : 'none'}
              className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400"
            >
              <button
                type="button"
                onClick={() => setSortKey(column.key)}
                className="rounded-lg px-2 py-1 transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-orange-700 focus-visible:ring-offset-2 motion-reduce:transition-none dark:hover:bg-zinc-900"
              >
                {column.label}
                {sortKey === column.key ? ' (sorted)' : ''}
              </button>
            </th>
          ))}
          <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">Status</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((appointment) => (
          <tr key={appointment.id} className="border-b border-zinc-100 dark:border-zinc-900">
            <td className="px-4 py-3 text-base tabular-nums text-zinc-900 dark:text-zinc-100">{appointment.containerNo}</td>
            <td className="min-w-0 px-4 py-3 text-base text-zinc-900 dark:text-zinc-100">
              <span className="block truncate" title={appointment.terminal}>{appointment.terminal}</span>
            </td>
            <td className="px-4 py-3 text-base tabular-nums text-zinc-700 dark:text-zinc-300">{formatWindow(appointment.windowStart)}</td>
            <td className="px-4 py-3 text-base text-zinc-700 dark:text-zinc-300">{STATUS_LABEL[appointment.status]}</td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}

import { describe, expect, it } from 'vitest'

import { sortAppointments, type DrayageAppointment } from './appointments'

const rows: DrayageAppointment[] = [
  { id: 'ap-9021', containerNo: 'MSCU4471880', terminal: 'Pier 400', windowStart: '2026-07-28T14:00:00Z', status: 'booked' },
  { id: 'ap-9022', containerNo: 'HLXU2298013', terminal: 'Berth 55', windowStart: '2026-07-28T09:30:00Z', status: 'arrived' },
]

describe('sortAppointments', () => {
  it('returns a new array and leaves the caller list in its original order', () => {
    const sorted = sortAppointments(rows, 'windowStart')

    expect(sorted).not.toBe(rows)
    expect(sorted.map((row) => row.id)).toEqual(['ap-9022', 'ap-9021'])
    expect(rows.map((row) => row.id)).toEqual(['ap-9021', 'ap-9022'])
  })

  it('sorts by terminal without disturbing the source order', () => {
    sortAppointments(rows, 'terminal')

    expect(rows.map((row) => row.id)).toEqual(['ap-9021', 'ap-9022'])
