import { useComplianceStream } from './useComplianceStream'
import type { ComplianceCheck } from './types'

interface DangerousGoodsTableProps {
  shipmentId: string
}

const OUTCOME_LABEL: Record<ComplianceCheck['outcome'], string> = {
  pass: 'Cleared',
  fail: 'Blocked, cannot load',
  pending: 'Awaiting inspector',
}

export function DangerousGoodsTable({ shipmentId }: DangerousGoodsTableProps) {
  const checks = useComplianceStream(shipmentId)

  if (checks.length === 0) {
    return (
      <p className="rounded-lg border border-zinc-200 p-6 text-base text-zinc-700 dark:border-zinc-800 dark:text-zinc-300">
        No dangerous goods declared on shipment {shipmentId}. Declared items appear here as the inspector clears them.
