      <thead>
        <tr className="border-b border-zinc-200 dark:border-zinc-800">
          <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">UN number</th>
          <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">Proper shipping name</th>
          <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">Class</th>
          <th scope="col" className="px-4 py-2 text-sm font-medium text-zinc-600 dark:text-zinc-400">Packing group</th>
