import { renderHook } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { subscribeComplianceChecks } from './compliance'
import { useComplianceStream } from './useComplianceStream'

vi.mock('./compliance', () => ({ subscribeComplianceChecks: vi.fn() }))

describe('useComplianceStream', () => {
  it('closes the compliance stream when the screen unmounts', () => {
    const unsubscribe = vi.fn()
    vi.mocked(subscribeComplianceChecks).mockReturnValue(unsubscribe)

    const { unmount } = renderHook(() => useComplianceStream('SHP-55120'))
    expect(unsubscribe).not.toHaveBeenCalled()

    unmount()
    expect(unsubscribe).toHaveBeenCalledTimes(1)
  })

  it('drops the old stream before opening one for another shipment', () => {
    const first = vi.fn()
    const second = vi.fn()
    vi.mocked(subscribeComplianceChecks).mockReturnValueOnce(first).mockReturnValueOnce(second)

    const { rerender } = renderHook(({ shipmentId }) => useComplianceStream(shipmentId), {
      initialProps: { shipmentId: 'SHP-55120' },
    })
    rerender({ shipmentId: 'SHP-55208' })

    expect(first).toHaveBeenCalledTimes(1)
    expect(subscribeComplianceChecks).toHaveBeenCalledTimes(2)
    expect(second).not.toHaveBeenCalled()
  })
})

