import { useState } from 'react'
import type { LoggedMeal, MealItem } from '../../types/meal'

export function useMealDraft(meal: LoggedMeal) {
  const [draft, setDraft] = useState<LoggedMeal>(meal)

  function removeItem(index: number) {
    draft.items.splice(index, 1)
    setDraft({ ...draft })
  }

  function addItem(item: MealItem) {
    draft.items.push(item)
    setDraft({ ...draft })
  }

  return { draft, removeItem, addItem }
}

