import { act, renderHook } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { useMealDraft } from './useMealDraft'

const savedMeal = {
  id: 'meal-8821',
  name: 'Post-run lunch',
  items: [
    { id: 'itm-4410', food: 'Brown rice, 180 g', calories: 234 },
    { id: 'itm-4411', food: 'Grilled paneer, 90 g', calories: 261 },
  ],
}

describe('useMealDraft', () => {
  it('leaves the saved meal untouched when an item is removed from the draft', () => {
    const saved = { ...savedMeal, items: [...savedMeal.items] }
    const { result } = renderHook(() => useMealDraft(saved))

    act(() => result.current.removeItem(0))

    expect(result.current.draft.items).toHaveLength(1)
    expect(saved.items).toHaveLength(2)
    expect(saved.items[0].food).toBe('Brown rice, 180 g')
  })

  it('removes two items one at a time without dropping the wrong row', () => {
    const saved = { ...savedMeal, items: [...savedMeal.items] }
    const { result } = renderHook(() => useMealDraft(saved))

    act(() => result.current.removeItem(1))
    act(() => result.current.removeItem(0))

    expect(result.current.draft.items).toHaveLength(0)
    expect(saved.items).toHaveLength(2)
  })
