import { useCallback, useEffect, useState } from 'react'

interface RestTimerOverlayProps {
  initialSeconds: number
  exerciseName: string
  onDone: () => void
}

export function RestTimerOverlay({ initialSeconds, exerciseName, onDone }: RestTimerOverlayProps) {
  const [seconds, setSeconds] = useState(initialSeconds)

  useEffect(() => {
    const id = window.setInterval(() => {
      setSeconds((current) => current - 1)
    }, 1000)
    return () => window.clearInterval(id)
  }, [])

  useEffect(() => {
    if (seconds <= 0) onDone()
  }, [seconds, onDone])

  const addThirty = useCallback(() => {
    setSeconds(seconds + 30)
  }, [])

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-zinc-950/70 p-4">
      <div role="dialog" aria-modal="true" aria-labelledby="rest-heading" className="w-full max-w-sm rounded-lg bg-white p-6 text-center shadow-lg dark:bg-zinc-900">
        <h2 id="rest-heading" className="text-lg font-semibold leading-tight text-zinc-900 dark:text-zinc-100">Rest before {exerciseName}</h2>
        <p aria-live="polite" className="mt-4 text-2xl font-semibold tabular-nums text-zinc-900 dark:text-zinc-100">{seconds}s</p>
        <div className="mt-6 flex justify-center gap-2">
          <button type="button" onClick={addThirty} className="rounded-lg border border-zinc-300 px-4 py-2 text-sm font-medium text-zinc-700 hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 active:scale-[0.98] dark:border-zinc-700 dark:text-zinc-300 dark:hover:bg-zinc-800">
