import { useEffect, useState } from 'react'
import { fetchVitals } from './telemetryApi'
import type { Vitals } from '../../types/telemetry'

export function useVitalsPoll(patientId: string, intervalMs: number) {
  const [vitals, setVitals] = useState<Vitals | null>(null)

  useEffect(() => {
    let active = true

    async function poll() {
      const next = await fetchVitals(patientId)
      if (active) setVitals(next)
    }

    poll()
    const id = window.setInterval(poll, intervalMs)

    return () => {
      active = false
      window.clearInterval(id)
    }
  }, [intervalMs])

  return vitals
}

