  beforeEach(() => {
    mockFetchVitals.mockReset()
    mockFetchVitals.mockImplementation(async (patientId: string) =>
      patientId === 'pt-4471'
        ? { heartRate: 96, rhythm: 'Sinus tachycardia' }
        : { heartRate: 61, rhythm: 'Normal sinus' },
    )
  })

