    const { result, rerender } = renderHook(({ id }) => useVitalsPoll(id, 5000), {
      initialProps: { id: 'pt-4471' },
    })

    await waitFor(() => expect(result.current?.heartRate).toBe(96))

    rerender({ id: 'pt-5093' })

    await waitFor(() => expect(result.current?.heartRate).toBe(61))
    expect(mockFetchVitals).toHaveBeenLastCalledWith('pt-5093')
  })

  it('clears the previous reading while the new patient is loading', async () => {
    const { result, rerender } = renderHook(({ id }) => useVitalsPoll(id, 5000), {
      initialProps: { id: 'pt-4471' },
    })

    await waitFor(() => expect(result.current?.heartRate).toBe(96))

    rerender({ id: 'pt-5093' })

    expect(result.current).toBeNull()
  })
})

