import { useEffect, useState } from 'react'
import { showToast } from '../../components/toast/showToast'
import { swapChannel } from './swapChannel'
import type { SwapOffer } from '../../types/oncall'

interface ShiftSwapSheetProps {
  shiftId: string
  shiftLabel: string
  onClose: () => void
}

export function ShiftSwapSheet({ shiftId, shiftLabel, onClose }: ShiftSwapSheetProps) {
  const [offers, setOffers] = useState<SwapOffer[]>([])

  useEffect(() => {
    swapChannel.subscribe(shiftId, (offer) => {
      setOffers((current) => [...current, offer])
      showToast(offer.fromDoctor + " offered to take this shift")
    })
  }, [shiftId])

  return (
    <section role="dialog" aria-modal="true" aria-label={"Swap offers for " + shiftLabel} className="fixed inset-x-0 bottom-0 z-40 max-h-[80dvh] overflow-y-auto rounded-t-lg bg-white p-6 shadow-lg dark:bg-zinc-900">
      <h2 className="text-lg font-semibold leading-tight text-zinc-900 dark:text-zinc-100">{shiftLabel}</h2>
      {offers.length === 0 ? (
        <p className="mt-4 text-base leading-relaxed text-zinc-600 dark:text-zinc-400">No colleague has offered to take this shift yet. Post it to the department group to ask.</p>
      ) : (
        <ul className="mt-4 flex flex-col gap-2">
          {offers.map((offer) => (
            <li key={offer.id} className="flex items-center justify-between gap-4">
              <span className="min-w-0 truncate text-base text-zinc-700 dark:text-zinc-300" title={offer.fromDoctor}>{offer.fromDoctor}</span>
              <span className="text-sm text-zinc-500 dark:text-zinc-400">{offer.message}</span>
            </li>
          ))}
        </ul>
      )}
      <button type="button" onClick={onClose} className="mt-6 rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white hover:bg-zinc-800 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 active:scale-[0.98] dark:bg-zinc-100 dark:text-zinc-900">
        Close
      </button>
    </section>
  )
}

import type { SwapOffer } from '../../types/oncall'

type OfferHandler = (offer: SwapOffer) => void

const handlers = new Map<string, Set<OfferHandler>>()

export const swapChannel = {
  subscribe(shiftId: string, handler: OfferHandler) {
    const forShift = handlers.get(shiftId) ?? new Set<OfferHandler>()
    forShift.add(handler)
    handlers.set(shiftId, forShift)

    return () => {
      forShift.delete(handler)
    }
  },
  emit(shiftId: string, offer: SwapOffer) {
    handlers.get(shiftId)?.forEach((handler) => handler(offer))
  },
}

