import { render, screen } from '@testing-library/react'
import { act } from 'react'
import { RouterProvider, createMemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

import { fetchLecture } from '../../api/lectures'
import type { Lecture } from '../../types/lecture'
import { LecturePlayer } from './LecturePlayer'

vi.mock('../../api/lectures')

const bio204: Lecture = {
  id: 'bio-204',
  title: 'Mitochondrial genetics',
  chapters: [
    { id: 'c-maternal', title: 'Maternal inheritance' },
    { id: 'c-hetero', title: 'Heteroplasmy' },
    { id: 'c-pedigree', title: 'Reading a pedigree' },
  ],
}

const stat118: Lecture = {
  id: 'stat-118',
  title: 'Sampling distributions',
  chapters: [{ id: 'c-se', title: 'Standard error' }],
}

const routes = [
  { path: '/lectures/:lectureId', element: <LecturePlayer /> },
  { path: '/lectures/:lectureId/chapters/:chapterIndex', element: <LecturePlayer /> },
]

describe('LecturePlayer', () => {
  it('marks the chapter from the URL as the current step', async () => {
    vi.mocked(fetchLecture).mockResolvedValue(bio204)
    render(<RouterProvider router={createMemoryRouter(routes, { initialEntries: ['/lectures/bio-204/chapters/2'] })} />)

    const current = await screen.findByRole('link', { current: 'step' })
    expect(current).toHaveTextContent('3. Reading a pedigree')
  })

  it('ignores a late response for a lecture the reader already left', async () => {
    let releaseFirst = () => {}
    vi.mocked(fetchLecture)
      .mockImplementationOnce(
        () =>
          new Promise<Lecture>((resolve) => {
            releaseFirst = () => resolve(bio204)
          }),
      )
      .mockResolvedValueOnce(stat118)

    const router = createMemoryRouter(routes, { initialEntries: ['/lectures/bio-204'] })
    render(<RouterProvider router={router} />)
    await act(async () => {
      await router.navigate('/lectures/stat-118')
    })
    await act(async () => {
      releaseFirst()
    })

    expect(await screen.findByRole('heading', { level: 1 })).toHaveTextContent('Sampling distributions')
    expect(screen.queryByText('Heteroplasmy')).toBeNull()
  })
})

