import { useNavigate, useParams } from 'react-router-dom'

import type { AwardKind } from '../../types/award'

export type WizardStep = 'applicant' | 'project' | 'budget' | 'review'

const STEPS: WizardStep[] = ['applicant', 'project', 'budget', 'review']

function isWizardStep(value: string | undefined): value is WizardStep {
  return STEPS.some((name) => name === value)
}

export function useWizardSteps(award: AwardKind) {
  const { step } = useParams()
  const navigate = useNavigate()
  const steps = award === 'travel' ? STEPS.filter((name) => name !== 'budget') : STEPS
  const current = isWizardStep(step) && steps.includes(step) ? step : steps[0]
  const index = steps.indexOf(current)

  return {
    step: current,
    index,
    total: steps.length,
    goBack: () => navigate(`/apply/${steps[Math.max(index - 1, 0)]}`),
    goNext: () => navigate(`/apply/${steps[Math.min(index + 1, steps.length - 1)]}`),
  }
}

