import { render } from '@testing-library/react'
import { act } from 'react'
import { RouterProvider, createMemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

import { useJumpShortcuts } from './useJumpShortcuts'

function Screen() {
  useJumpShortcuts()
  return <p>reference library</p>
}

const routes = [
  { path: '/', element: <Screen /> },
  { path: '/library', element: <Screen /> },
  { path: '/collections', element: <Screen /> },
]

function typeChord(second: string) {
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'g' }))
  window.dispatchEvent(new KeyboardEvent('keydown', { key: second }))
}

describe('useJumpShortcuts', () => {
  it('jumps to collections on g then c', async () => {
    const router = createMemoryRouter(routes, { initialEntries: ['/'] })
    render(<RouterProvider router={router} />)

    await act(async () => {
      typeChord('c')
    })

    expect(router.state.location.pathname).toBe('/collections')
  })

  it('removes the previous keydown listener when the route changes', async () => {
    const remove = vi.spyOn(window, 'removeEventListener')
    const router = createMemoryRouter(routes, { initialEntries: ['/'] })
    render(<RouterProvider router={router} />)

    await act(async () => {
      await router.navigate('/library')
    })

    expect(remove.mock.calls.filter(([type]) => type === 'keydown')).toHaveLength(1)
  })

  it('stops listening after unmount', async () => {
    const router = createMemoryRouter(routes, { initialEntries: ['/'] })
    const view = render(<RouterProvider router={router} />)
    view.unmount()

    await act(async () => {
      typeChord('c')
    })

    expect(router.state.location.pathname).toBe('/')
  })
})

