import userEvent from '@testing-library/user-event'
import { RouterProvider, createMemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

import { submitReview } from '../../api/reviews'
import type { ReviewDraft } from '../../types/review'
import { ReviewForm } from './ReviewForm'

vi.mock('../../api/reviews')

const draft: ReviewDraft = { recommendation: 'minor-revision', comments: 'Methods section needs the sample size.' }

function routesFor(nextSubmissionId: string | null) {
  return [
    {
      path: '/review/:submissionId',
      element: <ReviewForm submissionId="prep-4471" draft={draft} nextSubmissionId={nextSubmissionId} />,
    },
    { path: '/queue', element: <p>assignment queue</p> },
  ]
}

describe('ReviewForm', () => {
  it('files the review once when submit is double clicked', async () => {
    vi.mocked(submitReview).mockResolvedValue(undefined)
    const router = createMemoryRouter(routesFor(null), { initialEntries: ['/review/prep-4471'] })
    render(<RouterProvider router={router} />)

    const button = screen.getByRole('button', { name: 'Submit review' })
    await userEvent.dblClick(button)

    expect(submitReview).toHaveBeenCalledTimes(1)
  })

  it('replaces the submitted review in history instead of stacking it', async () => {
    vi.mocked(submitReview).mockResolvedValue(undefined)
    const router = createMemoryRouter(routesFor('prep-4502'), { initialEntries: ['/queue', '/review/prep-4471'] })
    render(<RouterProvider router={router} />)

    await userEvent.click(screen.getByRole('button', { name: 'Submit and open next assignment' }))

    expect(router.state.location.pathname).toBe('/review/prep-4502')
    expect(router.state.historyAction).toBe('REPLACE')
  })
})

