import { markSheetSeen } from '../features/specimens/sheetLog'

export function SpecimenRouteFrame() {
  const frameRef = useRef<HTMLDivElement>(null)
  const { pathname } = useLocation()

  useEffect(() => {
    const onIntersect: IntersectionObserverCallback = (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) markSheetSeen(entry.target.id)
      }
    }
    const observer = new IntersectionObserver(onIntersect, { rootMargin: '-40% 0px' })
    const sheets = frameRef.current?.querySelectorAll('[data-sheet]')
    if (!sheets || sheets.length === 0) return
    for (const sheet of sheets) {
      observer.observe(sheet)
    }
    return () => observer.disconnect()
  }, [pathname])

  return (
    <div ref={frameRef} className="mx-auto flex max-w-7xl flex-col gap-6 p-6">
      <Outlet />
    </div>
  )
}

