import { render } from '@testing-library/react'
import { act } from 'react'
import { RouterProvider, createMemoryRouter } from 'react-router-dom'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { SpecimenRouteFrame } from './SpecimenRouteFrame'

const constructed = vi.fn()
const observe = vi.fn()
const disconnect = vi.fn()

class StubIntersectionObserver {
  observe = observe
  unobserve = vi.fn()
  disconnect = disconnect
  takeRecords = () => []
  root = null
  rootMargin = ''
  thresholds = []

  constructor() {
    constructed()
  }
}

vi.stubGlobal('IntersectionObserver', StubIntersectionObserver)
const scrollIntoView = vi.fn()
Element.prototype.scrollIntoView = scrollIntoView

function ScannedSheets() {
  return (
    <>
      <figure id="sheet-1" data-sheet>
        Kew accession sheet 1
      </figure>
      <figure id="sheet-2" data-sheet>
        Kew accession sheet 2
      </figure>
    </>
  )
}

const routes = [
  {
    path: '/specimens/:accession',
    element: <SpecimenRouteFrame />,
    children: [{ index: true, element: <ScannedSheets /> }],
  },
  {
    path: '/specimens/:accession/unscanned',
    element: <SpecimenRouteFrame />,
    children: [{ index: true, element: <p>No sheets scanned yet</p> }],
  },
]

beforeEach(() => {
  constructed.mockClear()
  observe.mockClear()
  disconnect.mockClear()
  scrollIntoView.mockClear()
})

describe('SpecimenRouteFrame', () => {
  it('scrolls to the sheet named in the location hash', () => {
    render(<RouterProvider router={createMemoryRouter(routes, { initialEntries: ['/specimens/k000572/#sheet-2'] })} />)

    expect(scrollIntoView).toHaveBeenCalledTimes(1)
  })

  it('builds no observer for a specimen with no scanned sheets', () => {
    render(<RouterProvider router={createMemoryRouter(routes, { initialEntries: ['/specimens/k000572/unscanned'] })} />)

    expect(constructed).not.toHaveBeenCalled()
  })

  it('disconnects the observer when the specimen changes', async () => {
    const router = createMemoryRouter(routes, { initialEntries: ['/specimens/k000572'] })
    render(<RouterProvider router={router} />)

    await act(async () => {
      await router.navigate('/specimens/k001884')
    })

    expect(disconnect).toHaveBeenCalledTimes(1)
  })
})

