import type { Unit, UnitSummary } from '../types/unit'

const cache = new Map<string, Promise<Unit>>()

export async function fetchRecentUnits(): Promise<UnitSummary[]> {
  const response = await fetch('/api/units/recent')
  return response.json()
}

export function fetchUnit(unitId: string): Promise<Unit> {
  const pending = cache.get(unitId)
  if (pending) return pending
  const request = fetch(`/api/units/${unitId}`).then((response) => response.json() as Promise<Unit>)
  cache.set(unitId, request)
  return request
}

