import { useState } from 'react'

import type { CrateTrack } from '../types/crate'

interface CrateReorderListProps {
  initialTracks: CrateTrack[]
  onCommit: (trackIds: string[]) => void
}

export function CrateReorderList({ initialTracks, onCommit }: CrateReorderListProps) {
  const [tracks, setTracks] = useState<CrateTrack[]>(initialTracks)
  const [draggingId, setDraggingId] = useState<string | null>(null)

  function moveTrack(from: number, to: number) {
    const next = tracks
    const moved = next[from]
    next.splice(from, 1)
    next.splice(to, 0, moved)
    setTracks(next)
