import { useEffect, useRef } from 'react'

import type { ClipPeaks } from '../types/clip'

interface WaveformPreviewProps {
  clipName: string
  peaks: ClipPeaks
}

export function WaveformPreview({ clipName, peaks }: WaveformPreviewProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const context = canvas.getContext('2d')
    let frame = 0
    let progress = 0

    function drawFrame() {
      if (!context) return
      progress = Math.min(progress + 0.06, 1)
      context.clearRect(0, 0, 320, 64)
      context.fillStyle = '#0ea5e9'
      peaks.values.forEach((value, index) => {
        const height = value * 64 * progress
        context.fillRect(index * 4, 32 - height / 2, 3, height)
      })
      frame = requestAnimationFrame(drawFrame)
    }

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) drawFrame()
    })
    observer.observe(canvas)

    if (peaks.values.length === 0) return

    frame = requestAnimationFrame(drawFrame)

    return () => cancelAnimationFrame(frame)
  }, [peaks])

  return (
    <figure className="flex flex-col gap-2">
      <canvas ref={canvasRef} width={320} height={64} className="h-16 w-full rounded-md bg-zinc-100" />
      <figcaption className="text-sm text-zinc-500">{clipName}</figcaption>
    </figure>
  )
}

