import { render } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { WaveformPreview } from './WaveformPreview'

const observe = vi.fn()
const disconnect = vi.fn()

beforeEach(() => {
  observe.mockClear()
  disconnect.mockClear()
  vi.stubGlobal(
    'IntersectionObserver',
    class {
      observe = observe
      unobserve = vi.fn()
      disconnect = disconnect
      takeRecords = vi.fn()
    },
  )
})

describe('WaveformPreview', () => {
  it('disconnects the observer on unmount while the clip is still being analysed', () => {
    const { unmount } = render(<WaveformPreview clipName="Harbour gulls, 06:12" peaks={{ values: [] }} />)
    expect(observe).toHaveBeenCalledTimes(1)
    unmount()
    expect(disconnect).toHaveBeenCalledTimes(1)
  })

  it('disconnects the observer on unmount for an analysed clip', () => {
    const { unmount } = render(
      <WaveformPreview clipName="Tram bell, Praha 2" peaks={{ values: [0.2, 0.7, 0.4] }} />,
    )
    unmount()
    expect(disconnect).toHaveBeenCalledTimes(1)
  })
})

