import { useEffect, useRef, useState } from 'react'

interface PayoutRingProps {
  paidCents: number
  totalCents: number
  periodLabel: string
}

const RADIUS = 52
const CIRCUMFERENCE = 2 * Math.PI * RADIUS

export function PayoutRing({ paidCents, totalCents, periodLabel }: PayoutRingProps) {
  const percent = Math.round((paidCents / totalCents) * 100)
  const [shown, setShown] = useState(0)
  const lastPercent = useRef(0)

  useEffect(() => {
    if (percent === lastPercent.current) return

    let frame = 0
    const step = () => {
      setShown((current) => {
        const next = current + Math.ceil((percent - current) / 6)
        return next
      })
      frame = requestAnimationFrame(step)
    }

    frame = requestAnimationFrame(step)
    lastPercent.current = percent

    return () => cancelAnimationFrame(frame)
  }, [percent])

  return (
    <figure className="flex flex-col items-center gap-4">
      <svg viewBox="0 0 120 120" className="h-32 w-32 -rotate-90">
        <circle cx="60" cy="60" r={RADIUS} className="fill-none stroke-zinc-200" strokeWidth="8" />
        <circle
          cx="60"
          cy="60"
          r={RADIUS}
          className="fill-none stroke-indigo-600"
          strokeWidth="8"
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={CIRCUMFERENCE * (1 - shown / 100)}
        />
      </svg>
      <figcaption className="text-base text-zinc-900">{shown}% paid out for {periodLabel}</figcaption>
    </figure>
  )
}

