const percent = totalCents > 0 ? Math.round((paidCents / totalCents) * 100) : 0
const [shown, setShown] = useState(0)
const shownRef = useRef(0)
const lastPercent = useRef(0)

useEffect(() => {
  if (percent === lastPercent.current) return
  lastPercent.current = percent

  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    shownRef.current = percent
    setShown(percent)
    return
  }

  let frame = 0
  const step = () => {
    const delta = percent - shownRef.current
    if (delta === 0) return
    shownRef.current += Math.abs(delta) <= 6 ? delta : Math.trunc(delta / 6)
    setShown(shownRef.current)
    frame = requestAnimationFrame(step)
  }

  frame = requestAnimationFrame(step)

  return () => cancelAnimationFrame(frame)
}, [percent])

