import { render } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'
import { DocumentsDropzone } from './DocumentsDropzone'

function firePaste(file: File) {
  const event = new Event('paste') as ClipboardEvent
  Object.defineProperty(event, 'clipboardData', { value: { files: [file] } })
  window.dispatchEvent(event)
}

describe('DocumentsDropzone', () => {
  it('stops listening for paste after unmount', () => {
    const onFiles = vi.fn()
    const file = new File(['png-bytes'], 'site-plan-rev-c.png', { type: 'image/png' })
    const { unmount } = render(<DocumentsDropzone permitId="PRM-2088" onFiles={onFiles} />)
    firePaste(file)
    expect(onFiles).toHaveBeenCalledTimes(1)
    unmount()
    firePaste(file)
    expect(onFiles).toHaveBeenCalledTimes(1)
  })

  it('attaches a pasted file exactly once after repeated tab visits', () => {
    const onFiles = vi.fn()
    const file = new File(['pdf-bytes'], 'north-elevation.pdf', { type: 'application/pdf' })
    for (let visit = 0; visit < 3; visit += 1) {
      const { unmount } = render(<DocumentsDropzone permitId="PRM-2088" onFiles={onFiles} />)
      unmount()
    }
    render(<DocumentsDropzone permitId="PRM-2088" onFiles={onFiles} />)
    firePaste(file)
    expect(onFiles).toHaveBeenCalledTimes(1)
  })
})

