import { useState } from 'react'

interface PlanPreview {
  name: string
  url: string
}

interface PlanDropInputProps {
  onAccepted: (files: File[]) => void
}

const ACCEPTED_TYPES = ['application/pdf', 'image/png']

export function PlanDropInput({ onAccepted }: PlanDropInputProps) {
  const [previews, setPreviews] = useState<PlanPreview[]>([])
  const [rejectedName, setRejectedName] = useState<string | null>(null)

  const handleFiles = (list: FileList | null) => {
    const files = Array.from(list ?? [])
    if (files.length === 0) return
    const next = files.map((file) => ({ name: file.name, url: URL.createObjectURL(file) }))
    const unsupported = files.find((file) => !ACCEPTED_TYPES.includes(file.type))
    if (unsupported) {
      setRejectedName(unsupported.name)
      return
    }
    setRejectedName(null)
    setPreviews((prev) => [...prev, ...next])
    onAccepted(files)
  }

  return (
    <div className="flex flex-col gap-4">
      <label htmlFor="plan-files" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        Add plan files
      </label>
      <input
        id="plan-files"
        type="file"
        multiple
        accept=".pdf,.png"
        onChange={(event) => handleFiles(event.target.files)}
        className="text-sm text-zinc-600 dark:text-zinc-400"
      />
      {rejectedName && (
        <p role="alert" className="text-sm text-red-600 dark:text-red-400">
          {rejectedName} is not a supported plan format. Upload PDF or PNG sheets.
        </p>
      )}
      {previews.length === 0 ? (
        <p className="text-sm text-zinc-500 dark:text-zinc-400">No sheets added yet. Drop PDF or PNG plan sheets to build the set.</p>
      ) : (
        <ul className="grid grid-cols-2 gap-4 md:grid-cols-4">
          {previews.map((preview) => (
            <li key={preview.url}>
              <img src={preview.url} alt={preview.name + ' preview'} className="aspect-square w-full rounded object-cover" />
              <p className="mt-1 truncate text-sm text-zinc-600 dark:text-zinc-400" title={preview.name}>{preview.name}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

