import { useState } from 'react'
import { QueueRow } from './QueueRow'

interface PhotoQueueProps {
  onQueueChange: (files: File[]) => void
}

export function PhotoQueue({ onQueueChange }: PhotoQueueProps) {
  const [queue, setQueue] = useState<File[]>([])

  const addPhotos = (incoming: File[]) => {
    const fresh = incoming.filter((file) => !queue.includes(file))
    const next = [...queue, ...fresh]
    setQueue(next)
    onQueueChange(next)
  }

  return (
    <section className="flex flex-col gap-4">
      <label htmlFor="diary-photos" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
