        type="file"
        accept="image/*"
        multiple
        onChange={(event) => addPhotos(Array.from(event.target.files ?? []))}
        className="text-sm text-zinc-600 dark:text-zinc-400"
      />
      {queue.length === 0 ? (
        <p className="text-sm text-zinc-500 dark:text-zinc-400">No photos queued yet. Add today's site photos to start the entry.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {queue.map((file) => (
            <QueueRow key={file.name + file.lastModified} file={file} />
          ))}
        </ul>
      )}
