import { useEffect, useState } from 'react'
import { fetchFlightStatus } from './statusApi'
import type { FlightStatus } from './statusApi'

interface FlightStatusBadgeProps {
  flightId: string
  onReady: () => void
}

const LABEL: Record<FlightStatus, string> = {
  queued: 'Queued for processing',
  processing: 'Processing footage',
  ready: 'Ready to review',
}

const TONE: Record<FlightStatus, string> = {
  queued: 'bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300',
  processing: 'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300',
  ready: 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300',
}

export function FlightStatusBadge({ flightId, onReady }: FlightStatusBadgeProps) {
  const [status, setStatus] = useState<FlightStatus>('queued')

  useEffect(() => {
    const poll = async () => {
      const next = await fetchFlightStatus(flightId)
      setStatus(next)
      if (next === 'ready') onReady()
    }
    poll()
    setInterval(poll, 5000)
  }, [flightId, onReady])

  return (
    <span className={'inline-flex items-center gap-2 rounded-full px-3 py-1 text-sm font-medium ' + TONE[status]}>
      <span aria-hidden="true" className={status === 'processing' ? 'h-2 w-2 animate-pulse rounded-full bg-current motion-reduce:animate-none' : 'h-2 w-2 rounded-full bg-current'} />
      {LABEL[status]}
    </span>
  )
}

