import { useState } from 'react'
import { putToStorage } from './uploadClient'

type UploadStatus = 'idle' | 'uploading' | 'done' | 'failed'

interface PhotoPanelProps {
  inspectionId: string
  onDone: (fileName: string) => void
}

const STATUS_COPY: Record<UploadStatus, string> = {
  idle: 'No photo attached',
  uploading: 'Uploading photo',
  done: 'Uploaded',
  failed: 'Upload failed. Check your connection and retry.',
}

export function PhotoPanel({ inspectionId, onDone }: PhotoPanelProps) {
  const [status, setStatus] = useState<UploadStatus>('idle')

  const handleFile = async (file: File) => {
    setStatus('uploading')
    try {
      putToStorage(inspectionId, file)
      setStatus('done')
      onDone(file.name)
    } catch {
      setStatus('failed')
    }
  }

  return (
    <div className="flex flex-col gap-4">
      <label htmlFor="inspection-photo" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        Defect photo
      </label>
      <input
        id="inspection-photo"
        type="file"
        accept="image/*"
        onChange={(event) => {
          const file = event.target.files?.[0]
          if (file) handleFile(file)
        }}
        className="text-sm text-zinc-600 dark:text-zinc-400"
      />
      <p role="status" aria-live="polite" className="text-sm text-zinc-600 dark:text-zinc-400">
        {STATUS_COPY[status]}
      </p>
    </div>
  )
}

interface PresignResponse {
  url: string
}

export async function putToStorage(inspectionId: string, file: File): Promise<void> {
  const presignRes = await fetch(`/api/inspections/${inspectionId}/presign?name=${encodeURIComponent(file.name)}`)
  const { url } = (await presignRes.json()) as PresignResponse
  fetch(url, { method: 'PUT', body: file, headers: { 'Content-Type': file.type } })
}

