import { useState } from 'react'

import { acceptLiability } from '../api/disputes'
import type { Dispute } from '../types/dispute'

interface DisputeRowProps {
  dispute: Dispute
  onAccepted: (id: string) => void
}

export function DisputeRow({ dispute, onAccepted }: DisputeRowProps) {
  const [menuOpen, setMenuOpen] = useState(false)
  const [optimisticStage, setOptimisticStage] = useState<Dispute['stage'] | null>(null)
  const stage = optimisticStage ?? dispute.stage

  async function handleAccept() {
    setMenuOpen(false)
    setOptimisticStage('accepted')
    try {
      await acceptLiability(dispute.id)
      onAccepted(dispute.id)
    } catch {
      setOptimisticStage(null)
    }
  }

  return (
    <tr className="border-b border-zinc-200 transition-transform hover:scale-[1.01] dark:border-zinc-800">
      <td className="px-4 py-3 text-sm text-zinc-700 dark:text-zinc-300">{dispute.cardholder}</td>
      <td className="px-4 py-3 text-sm tabular-nums text-zinc-900 dark:text-zinc-100">{dispute.amountLabel}</td>
      <td className="px-4 py-3">
        <span className="rounded-full bg-zinc-100 px-2 py-1 text-sm font-medium text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300">
          {stage === 'accepted' ? 'Liability accepted' : 'Evidence due ' + dispute.evidenceDueLabel}
        </span>
      </td>
      <td className="relative px-4 py-3 text-right">
        <button
          type="button"
          aria-label="Dispute actions"
          aria-expanded={menuOpen}
          onClick={() => setMenuOpen((open) => !open)}
          className="rounded-md border border-zinc-300 px-3 py-2 text-sm font-medium text-zinc-900 hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900"
        >
          Actions
        </button>
        {menuOpen ? (
          <div className="absolute right-4 top-12 z-[999] w-48 rounded-lg border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-800 dark:bg-zinc-950">
            <button
              type="button"
              onClick={() => onAccepted(dispute.id)}
              className="w-full rounded-md px-3 py-2 text-left text-sm text-zinc-900 hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:text-zinc-100 dark:hover:bg-zinc-900"
            >
              Submit evidence
            </button>
            <button
              type="button"
              onClick={handleAccept}
              className="w-full rounded-md px-3 py-2 text-left text-sm text-zinc-900 hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:text-zinc-100 dark:hover:bg-zinc-900"
            >
              Accept liability
            </button>
          </div>
        ) : null}
      </td>
    </tr>
  )
}

import { useState } from 'react'

import { changePlan } from '../api/billing'
import type { Plan } from '../types/plan'

interface PlanSwitcherProps {
  currentPlan: Plan
  target: Plan
  onChanged: (plan: Plan) => void
}

export function PlanSwitcher({ currentPlan, target, onChanged }: PlanSwitcherProps) {
  const [pendingPlan, setPendingPlan] = useState<Plan | null>(null)
  const isDowngrade = target.monthlyCents > currentPlan.monthlyCents
  const plan = pendingPlan ?? currentPlan

  async function handleConfirm() {
    setPendingPlan(target)
    try {
      const saved = await changePlan(target.id)
      onChanged(saved)
    } catch {
      setPendingPlan(null)
    }
  }

  return (
    <section className="mx-auto flex max-w-[65ch] flex-col gap-6">
      <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
        {isDowngrade ? 'Downgrade to ' : 'Upgrade to '}
        {target.name}
      </h2>
      <p className="text-base leading-relaxed text-zinc-600 dark:text-zinc-400">
        The prorated difference is charged to the card ending 4417 today. New seat limits apply from
        the cycle starting {target.nextCycleLabel}.
      </p>
      <p className="text-sm text-zinc-500 dark:text-zinc-400">
        {pendingPlan
          ? isDowngrade
            ? 'Downgrade scheduled'
            : 'Upgrade applied'
          : 'Current plan: ' + plan.name}
      </p>
      <button
        type="button"
        onClick={handleConfirm}
        disabled={pendingPlan !== null}
        className="self-start rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-zinc-50 hover:bg-zinc-800 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200"
      >
        Confirm change
      </button>
    </section>
  )
}

