import { useCallback, useState } from 'react'

import { settleUp } from '../../api/split'
import type { Settlement } from '../../types/settlement'

interface UseSettleUpResult {
  rows: Settlement[]
  settle: (settlement: Settlement) => Promise<void>
}

export function useSettleUp(settlements: Settlement[], refetch: () => Promise<void>): UseSettleUpResult {
  const [optimistic, setOptimistic] = useState<Settlement[]>([])

  const rows = settlements.map((row) =>
    optimistic.includes(row) ? { ...row, status: 'settled' as const } : row,
  )

  const settle = useCallback(
    async (settlement: Settlement) => {
      setOptimistic((current) => [...current, settlement])
      try {
        await settleUp(settlement.id)
        await refetch()
      } catch {
        setOptimistic((current) => current.filter((row) => row !== settlement))
      }
    },
    [refetch],
  )

  return { rows, settle }
}

