import { useCallback, useEffect, useState } from 'react'

import { settleUp } from '../../api/split'
import type { Settlement } from '../../types/settlement'

interface UseSettleUpResult {
  rows: Settlement[]
  settle: (settlement: Settlement) => Promise<void>
}

export function useSettleUp(settlements: Settlement[], refetch: () => Promise<void>): UseSettleUpResult {
  const [optimisticIds, setOptimisticIds] = useState<string[]>([])

  const rows = settlements.map((row) =>
    optimisticIds.includes(row.id) ? { ...row, status: 'settled' as const } : row,
  )

  useEffect(() => {
    setOptimisticIds((current) =>
      current.filter((id) =>
        settlements.some((row) => row.id === id && row.status !== 'settled'),
      ),
    )
  }, [settlements])

  const settle = useCallback(
    async (settlement: Settlement) => {
      setOptimisticIds((current) => [...current, settlement.id])
      try {
        await settleUp(settlement.id)
        await refetch()
      } catch {
        setOptimisticIds((current) => current.filter((id) => id !== settlement.id))
      }
    },
    [refetch],
  )

