import { act, renderHook } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { settleUp } from '../../api/split'
import { useSettleUp } from './useSettleUp'
import type { Settlement } from '../../types/settlement'

vi.mock('../../api/split', () => ({ settleUp: vi.fn(async () => undefined) }))

const owed: Settlement = {
  id: 'stl_7841',
  fromName: 'Priya Raman',
  toName: 'Halima Yusuf',
  amountCents: 1840,
  status: 'owed',
}

describe('useSettleUp', () => {
  it('keeps the row settled when the refetched list still reports it as owed', async () => {
    const refetch = vi.fn(async () => undefined)
    const { result, rerender } = renderHook(({ rows }) => useSettleUp(rows, refetch), {
      initialProps: { rows: [owed] },
    })

    await act(async () => {
      await result.current.settle(owed)
    })
    rerender({ rows: [{ ...owed }] })

    expect(result.current.rows[0].status).toBe('settled')
  })

  it('rolls the row back to owed when the settle request is declined', async () => {
    vi.mocked(settleUp).mockRejectedValueOnce(new Error('gateway declined'))
    const refetch = vi.fn(async () => undefined)
    const { result } = renderHook(({ rows }) => useSettleUp(rows, refetch), {
      initialProps: { rows: [owed] },
    })

    await act(async () => {
      await result.current.settle(owed)
    })

    expect(result.current.rows[0].status).toBe('owed')
  })
})

