import { useCallback, useState } from 'react'

import { pinRecipient } from '../../api/recipients'
import type { Recipient } from '../../types/recipient'

interface UseRecipientPinsResult {
  rows: Recipient[]
  pin: (id: string) => Promise<void>
}

export function useRecipientPins(recipients: Recipient[]): UseRecipientPinsResult {
  const [pinnedIds, setPinnedIds] = useState<string[]>([])

  const pin = useCallback(async (id: string) => {
    setPinnedIds((current) => [...current, id])
    try {
      const saved = await pinRecipient(id)
      setPinnedIds(saved.pinnedIds)
    } catch {
      setPinnedIds((current) => current.filter((pinned) => pinned !== id))
    }
  }, [])

  const rows = recipients.map((recipient) => ({
    ...recipient,
    pinned: recipient.pinned || pinnedIds.includes(recipient.id),
  }))

  return { rows, pin }
}

import { useEffect } from 'react'

import { useRecipientPins } from './useRecipientPins'
import type { Recipient } from '../../types/recipient'

interface RecipientDrawerProps {
  recipients: Recipient[]
  onClose: () => void
  onPinned: (pinnedIds: string[]) => void
}

export function RecipientDrawer({ recipients, onClose, onPinned }: RecipientDrawerProps) {
  const { rows, pin } = useRecipientPins(recipients)

  useEffect(() => {
    function handleKey(event: KeyboardEvent) {
      if (event.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [onClose])

  return (
    <aside className="fixed inset-y-0 right-0 z-40 flex w-96 flex-col gap-6 border-l border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-950">
      <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">Send again</h2>
      <ul className="flex flex-col gap-2">
        {rows.map((recipient) => (
          <li key={recipient.id} className="flex items-center justify-between gap-4">
            <div className="min-w-0">
              <p className="truncate text-base text-zinc-900 dark:text-zinc-100" title={recipient.name}>
                {recipient.name}
              </p>
              <p className="text-sm text-zinc-500 dark:text-zinc-400">{recipient.bankLabel}</p>
            </div>
            <button
              type="button"
              aria-label={recipient.pinned ? 'Unpin ' + recipient.name : 'Pin ' + recipient.name}
              aria-pressed={recipient.pinned}
              onClick={() => pin(recipient.id)}
