import { useCallback, useEffect, useRef, useState } from 'react'

import { pinRecipient } from '../../api/recipients'
import type { Recipient } from '../../types/recipient'

interface UseRecipientPinsResult {
  rows: Recipient[]
  pin: (id: string) => Promise<void>
}

export function useRecipientPins(
  recipients: Recipient[],
  onPinned: (pinnedIds: string[]) => void,
): UseRecipientPinsResult {
  const [pinnedIds, setPinnedIds] = useState<string[]>([])
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    return () => {
      mountedRef.current = false
    }
  }, [])

  const pin = useCallback(
    async (id: string) => {
      setPinnedIds((current) => [...current, id])
      try {
        const saved = await pinRecipient(id)
        onPinned(saved.pinnedIds)
        if (mountedRef.current) setPinnedIds(saved.pinnedIds)
      } catch {
        if (mountedRef.current) {
          setPinnedIds((current) => current.filter((pinned) => pinned !== id))
        }
      }
    },
    [onPinned],
  )

