import { act, renderHook } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

import { pinRecipient } from '../../api/recipients'
import { useRecipientPins } from './useRecipientPins'
import type { Recipient } from '../../types/recipient'

vi.mock('../../api/recipients', () => ({ pinRecipient: vi.fn() }))

const recipients: Recipient[] = [
  { id: 'rcp_2290', name: 'Halima Yusuf', bankLabel: 'GTBank 0142', pinned: false },
  { id: 'rcp_3311', name: 'Tomas Ibarra', bankLabel: 'BBVA 8836', pinned: false },
]

describe('useRecipientPins', () => {
  it('reports the confirmed pins even when the drawer closed before the response', async () => {
    let confirm: (value: { pinnedIds: string[] }) => void = () => {}
    vi.mocked(pinRecipient).mockReturnValueOnce(
      new Promise((resolve) => {
        confirm = resolve
      }),
    )
    const onPinned = vi.fn()
    const { result, unmount } = renderHook(() => useRecipientPins(recipients, onPinned))

    let pending = Promise.resolve()
    act(() => {
      pending = result.current.pin('rcp_2290')
    })
    unmount()
    await act(async () => {
      confirm({ pinnedIds: ['rcp_2290'] })
      await pending
    })

    expect(onPinned).toHaveBeenCalledWith(['rcp_2290'])
  })

  it('drops the pin again when the request is rejected', async () => {
    vi.mocked(pinRecipient).mockRejectedValueOnce(new Error('recipient locked'))
    const { result } = renderHook(() => useRecipientPins(recipients, vi.fn()))

    await act(async () => {
      await result.current.pin('rcp_3311')
    })

    expect(result.current.rows[1].pinned).toBe(false)
  })
})

