import { useState } from 'react'

import { addExtraPayment } from '../api/loans'
import type { ScheduledPayment } from '../types/loan'

interface RepaymentScheduleProps {
  loanId: string
  currency: string
  locale: string
  payments: ScheduledPayment[]
}

export function RepaymentSchedule({ loanId, currency, locale, payments }: RepaymentScheduleProps) {
  const [extra, setExtra] = useState<ScheduledPayment[]>([])
  const rows = [...payments, ...extra].sort((a, b) => a.dueDate.localeCompare(b.dueDate))

  async function handleExtraPayment(amountCents: number, dueDate: string) {
    const optimistic: ScheduledPayment = {
      id: 'extra-' + dueDate,
      kind: 'extra',
      amountCents,
      dueDate,
      amountLabel: '$' + (amountCents / 100).toFixed(2),
      dueDateLabel: new Date(dueDate).toLocaleDateString(),
    }
    setExtra((current) => [...current, optimistic])
    try {
      await addExtraPayment(loanId, { amountCents, dueDate })
    } catch {
      setExtra((current) => current.filter((row) => row.id !== optimistic.id))
    }
  }

  return (
    <table className="w-full border-collapse text-left">
      <caption className="sr-only">Repayment schedule for loan {loanId}</caption>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id} className="border-b border-zinc-200 dark:border-zinc-800">
            <td className="px-4 py-3 text-sm text-zinc-700 dark:text-zinc-300">{row.dueDateLabel}</td>
            <td className="px-4 py-3 text-sm tabular-nums text-zinc-900 dark:text-zinc-100">{row.amountLabel}</td>
            <td className="px-4 py-3 text-sm text-zinc-500 dark:text-zinc-400">
              {row.kind === 'extra' ? 'Extra payment' : 'Scheduled'}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}

const CURRENCY_FORMATTERS = new Map<string, Intl.NumberFormat>()

export function formatMoney(amountCents: number, currency: string, locale: string): string {
  const key = locale + ':' + currency
  let formatter = CURRENCY_FORMATTERS.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, { style: 'currency', currency })
    CURRENCY_FORMATTERS.set(key, formatter)
  }
  return formatter.format(amountCents / 100)
}

export function formatDueDate(isoDate: string, locale: string): string {
  return new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeZone: 'UTC' }).format(
    new Date(isoDate),
  )
}

