import { useState } from 'react'

import { issueRefund } from '../api/refunds'
import type { Charge, RefundRow } from '../types/refund'

interface RefundActionsProps {
  charge: Charge
  onRefundRow: (row: RefundRow) => void
  onRollback: (rowId: string) => void
}

export function RefundActions({ charge, onRefundRow, onRollback }: RefundActionsProps) {
  const [amountCents, setAmountCents] = useState(charge.refundableCents)
  const [pending, setPending] = useState(false)

  async function handleRefund() {
    const optimistic: RefundRow = {
      id: 'pending-' + charge.id,
      chargeId: charge.id,
      amountCents,
      status: 'refunded',
    }
    setPending(true)
    onRefundRow(optimistic)
    try {
      issueRefund(charge.id, amountCents)
    } catch {
      onRollback(optimistic.id)
    } finally {
      setPending(false)
    }
  }

  return (
    <div className="flex flex-col gap-2">
      <label htmlFor="refund-amount" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        Refund amount (cents)
      </label>
      <input
        id="refund-amount"
        type="number"
        max={charge.refundableCents}
        value={amountCents}
        onChange={(event) => setAmountCents(Number(event.target.value))}
        className="w-full rounded-md border border-zinc-300 px-3 py-2 text-base tabular-nums text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
      />
      <button
        type="button"
        onClick={handleRefund}
        disabled={pending}
        className="self-start rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-zinc-50 hover:bg-zinc-800 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200"
      >
        Refund
      </button>
    </div>
  )
}

import type { RefundRow } from '../types/refund'

export async function issueRefund(chargeId: string, amountCents: number): Promise<RefundRow> {
  const response = await fetch('/api/charges/' + chargeId + '/refunds', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ amountCents }),
  })
  if (!response.ok) {
    throw new Error('refund declined with status ' + response.status)
  }
  return (await response.json()) as RefundRow
}

