import { useState } from 'react'

import { setRoundUpMultiplier } from '../api/savings'
import { cn } from '../lib/cn'
import type { RoundUpRule } from '../types/savings'

interface RoundUpRuleRowProps {
  rule: RoundUpRule
  className?: string
  onChanged: (rule: RoundUpRule) => void
}

const MULTIPLIERS = [1, 2, 5]

export function RoundUpRuleRow({ rule, className = '', onChanged }: RoundUpRuleRowProps) {
  const [optimisticMultiplier, setOptimisticMultiplier] = useState<number | null>(null)
  const [saving, setSaving] = useState(false)
  const multiplier = optimisticMultiplier ?? rule.multiplier

  async function handleSelect(next: number) {
    setSaving(true)
    setOptimisticMultiplier(next)
    try {
      const saved = await setRoundUpMultiplier(rule.id, next)
      onChanged(saved)
    } catch {
      setOptimisticMultiplier(null)
    } finally {
      setSaving(false)
    }
  }

  return (
    <li className={'flex items-center justify-between gap-4 rounded-lg border border-zinc-200 p-4 ' + (saving ? 'bg-amber-50 ' : 'bg-white ') + className}>
      <div className="min-w-0">
        <p className="truncate text-base text-zinc-900 dark:text-zinc-100" title={rule.accountName}>
          {rule.accountName}
        </p>
        <p className="text-sm text-zinc-500 dark:text-zinc-400">Rounds every card purchase up</p>
      </div>
      <div className="flex items-center gap-2">
        {MULTIPLIERS.map((value) => (
          <button
            key={value}
            type="button"
            aria-pressed={value === multiplier}
            onClick={() => handleSelect(value)}
            disabled={saving}
            className={cn(
              'rounded-md border border-zinc-300 px-3 py-2 text-sm font-medium tabular-nums text-zinc-900 hover:bg-zinc-50 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-900',
              value === multiplier && 'border-zinc-900 dark:border-zinc-100',
            )}
          >
            {value}x
          </button>
        ))}
      </div>
    </li>
  )
}

import { useState } from 'react'
import type { FormEvent } from 'react'

import { requestAdvance } from '../../api/advances'
import { useAdvanceQueue } from './useAdvanceQueue'

interface AdvanceRequestFormProps {
  availableCents: number
  payDateLabel: string
}

export function AdvanceRequestForm({ availableCents, payDateLabel }: AdvanceRequestFormProps) {
  const { queued, queueAdvance, rollback } = useAdvanceQueue()
  const [amountUsd, setAmountUsd] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [validationMessage, setValidationMessage] = useState<string | null>(null)

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setSubmitting(true)
    const amountCents = Math.round(Number(amountUsd) * 100)
    const rowId = queueAdvance(amountCents)

    if (amountCents > availableCents) {
      setValidationMessage('You can request up to USD ' + availableCents / 100 + ' before ' + payDateLabel + '.')
      return
    }

    try {
      await requestAdvance(amountCents)
      setValidationMessage(null)
    } catch {
      rollback(rowId)
      setValidationMessage('The advance did not go through. Nothing was taken from your pay.')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-4">
      <label htmlFor="advance-amount" className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
        Advance amount (USD)
      </label>
      <input
        id="advance-amount"
        type="number"
        inputMode="decimal"
        value={amountUsd}
        onChange={(event) => setAmountUsd(event.target.value)}
        className="w-full rounded-md border border-zinc-300 px-3 py-2 text-base tabular-nums text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
      />
      {validationMessage ? <p className="text-sm text-red-700 dark:text-red-400">{validationMessage}</p> : null}
      <button
        type="submit"
        disabled={submitting}
        className="self-start rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-zinc-50 hover:bg-zinc-800 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200"
      >
        Request advance
      </button>
      <ul className="flex flex-col gap-2">
        {queued.map((row) => (
          <li key={row.id} className="flex items-center justify-between gap-4 text-sm text-zinc-600 dark:text-zinc-400">
            <span className="tabular-nums">USD {row.amountCents / 100}</span>
            <span>Pending</span>
          </li>
        ))}
      </ul>
    </form>
  )
}

import { useCallback, useState } from 'react'

import type { QueuedAdvance } from '../../types/advance'

let nextQueueId = 0

export function useAdvanceQueue() {
  const [queued, setQueued] = useState<QueuedAdvance[]>([])

  const queueAdvance = useCallback((amountCents: number) => {
    nextQueueId += 1
    const id = 'queued-' + nextQueueId
    setQueued((current) => [...current, { id, amountCents, status: 'pending' }])
    return id
  }, [])

  const rollback = useCallback((id: string) => {
    setQueued((current) => current.filter((row) => row.id !== id))
  }, [])

  return { queued, queueAdvance, rollback }
}

