import { useEffect, useRef, useState } from 'react'

import type { FrostAlert } from '../../types/frost'

interface Viewport {
  scrollTop: number
  height: number
}

const ROW_HEIGHT = 56
const OVERSCAN = 6

export function useAlertWindow(alerts: FrostAlert[], viewport: Viewport) {
  const [visible, setVisible] = useState<FrostAlert[]>([])
  const [offsetY, setOffsetY] = useState(0)
  const lastRange = useRef<{ start: number; end: number } | null>(null)

  useEffect(() => {
    const start = Math.max(0, Math.floor(viewport.scrollTop / ROW_HEIGHT) - OVERSCAN)
    const end = Math.min(alerts.length, start + Math.ceil(viewport.height / ROW_HEIGHT) + OVERSCAN * 2)
    const range = { start, end }

    if (range === lastRange.current) return

    lastRange.current = range
    setVisible(alerts.slice(start, end))
    setOffsetY(start * ROW_HEIGHT)
  }, [alerts, viewport.scrollTop, viewport.height])

  return { visible, offsetY }
}

