const ROW_HEIGHT = 56
const OVERSCAN = 5
const VISIBLE_ROWS = 24

interface ObservationListProps {
  accountId: string
  total: number
}

export function ObservationList({ accountId, total }: ObservationListProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [scrollTop, setScrollTop] = useState(0)
  const { rowAt, ensureLoaded } = useObservationPages(accountId)

  const start = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - OVERSCAN)
  const end = Math.min(total, start + VISIBLE_ROWS + OVERSCAN * 2)
  const rows: Observation[] = []
  for (let i = start; i < end; i += 1) rows.push(rowAt(i))
  ensureLoaded(start, end)

  return (
    <div
      ref={scrollRef}
      onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}
      className="relative h-96 overflow-y-auto"
    >
      <div style={{ height: total * ROW_HEIGHT }} className="relative">
        {rows.map((observation, i) => (
          <ObservationRow key={observation.id} observation={observation} top={(start + i) * ROW_HEIGHT} />
        ))}
      </div>
    </div>
  )
}

