import { rackWindow, WHEEL_ROW_HEIGHT } from './rackWindow'

const wheels = Array.from({ length: 4180 }, (_, i) => ({
  id: 'W-' + String(20260101 + i),
  make: i % 3 === 0 ? 'Tomme de Savoie' : 'Comte',
  rack: 'Cave 2 / Rack ' + (Math.floor(i / 40) + 1),
  agingDays: 30 + (i % 210),
}))

describe('rackWindow', () => {
  it('includes the last wheel when the rack is scrolled to the bottom', () => {
    const viewportHeight = 640
    const scrollTop = wheels.length * WHEEL_ROW_HEIGHT - viewportHeight

    const win = rackWindow(wheels, scrollTop, viewportHeight)

    expect(win.wheels.at(-1)?.id).toBe(wheels[wheels.length - 1].id)
  })

  it('keeps the spacer height equal to every wheel row', () => {
    const win = rackWindow(wheels, 0, 640)

    expect(win.totalHeight).toBe(wheels.length * WHEEL_ROW_HEIGHT)
    expect(win.offsetY).toBe(0)
  })
})

