import { primeRateCache, readCachedRate } from '../../lib/rates'
import type { Folio, FolioLine } from '../../types/folio'

export async function loadFolioLines(folio: Folio, locale: string): Promise<FolioLine[]> {
  primeRateCache(folio.currency, folio.settlementCurrency)
  const rate = readCachedRate(folio.currency, folio.settlementCurrency) ?? 1
  const money = new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: folio.settlementCurrency,
  })

  return folio.charges.map((charge) => ({
    id: charge.id,
    label: charge.description,
    amount: money.format((charge.amountMinor / 100) * rate),
  }))
}

