import { render, screen } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { FolioTotals } from './FolioTotals'
import { loadFolioLines } from './folioLines'

vi.mock('./folioLines', () => ({ loadFolioLines: vi.fn() }))

const folio = {
  id: 'fol_20418',
  currency: 'EUR',
  settlementCurrency: 'GBP',
  charges: [
    { id: 'chg_1', description: 'Room 412, two nights', amountMinor: 48000 },
    { id: 'chg_2', description: 'Spa treatment, Ilse Bergmann', amountMinor: 9500 },
  ],
}

describe('FolioTotals', () => {
  beforeEach(() => {
    vi.mocked(loadFolioLines).mockReset()
  })

  it('renders one row per converted charge', async () => {
    vi.mocked(loadFolioLines).mockResolvedValue([
      { id: 'chg_1', label: 'Room 412, two nights', amount: 'GBP 409.20' },
      { id: 'chg_2', label: 'Spa treatment, Ilse Bergmann', amount: 'GBP 80.99' },
    ])

    render(<FolioTotals folio={folio} locale="en-GB" />)

    expect(await screen.findByText('GBP 409.20')).toBeInTheDocument()
    expect(screen.getByText('GBP 80.99')).toBeInTheDocument()
  })

  it('surfaces a retry action when the rate lookup rejects', async () => {
    vi.mocked(loadFolioLines).mockRejectedValue(new Error('Rate lookup failed with 503'))

    render(<FolioTotals folio={folio} locale="en-GB" />)

    expect(await screen.findByRole('alert')).toHaveTextContent('exchange rate')
    expect(screen.getByRole('button', { name: 'Retry rate lookup' })).toBeInTheDocument()
  })
})

