import { useEffect, useState } from 'react'

import { formatOccupancy } from '../../lib/occupancyLabel'
import { PitchTile } from './PitchTile'
import type { Pitch } from '../../types/pitch'

interface OccupancyBoardProps {
  pitches: Pitch[]
  locale: string
}

export function OccupancyBoard({ pitches, locale }: OccupancyBoardProps) {
  const [summary, setSummary] = useState(() => formatOccupancy(pitches, locale))

  useEffect(() => {
    const id = window.setInterval(() => {
      setSummary(formatOccupancy(pitches, locale))
    }, 30000)

    return () => window.clearInterval(id)
  }, [])

  return (
    <section className="flex flex-col gap-6">
      <h2 className="text-xl font-semibold text-zinc-900 dark:text-zinc-100">Pitch occupancy</h2>
      <p className="text-sm tabular-nums text-zinc-500 dark:text-zinc-400">{summary}</p>
      <div className="grid grid-cols-2 gap-4 md:grid-cols-6">
        {pitches.map((pitch) => (
          <PitchTile key={pitch.id} pitch={pitch} locale={locale} />
        ))}
      </div>
    </section>
  )
}

import type { Pitch } from '../types/pitch'

export function formatOccupancy(pitches: Pitch[], locale: string): string {
  const occupied = pitches.filter((pitch) => pitch.status === 'occupied').length
  const share = new Intl.NumberFormat(locale, {
    style: 'percent',
    maximumFractionDigits: 0,
  }).format(occupied / pitches.length)
  const updated = new Date().toLocaleTimeString(locale, { hour: '2-digit', minute: '2-digit' })

  return occupied + ' of ' + pitches.length + ' pitches occupied (' + share + '), updated ' + updated
}

