import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { ChatMessageRow } from './ChatMessageRow'

const message = {
  id: 'msg-40218',
  author: 'Priya Raman',
  body: 'run it back, the reset is up in 40 seconds',
  isMod: false,
}

describe('ChatMessageRow', () => {
  it('keeps only the pinned background on a pinned row', () => {
    render(
      <ul>
        <ChatMessageRow message={message} isPinned />
      </ul>,
    )
    const row = screen.getByRole('listitem')
    expect(row.className).toContain('bg-amber-100')
    expect(row.className).not.toContain('bg-white')
  })

  it('marks a pinned row with a label, not color alone', () => {
    render(
      <ul>
        <ChatMessageRow message={message} isPinned />
      </ul>,
    )
    expect(screen.getByText('Pinned')).toBeInTheDocument()
  })

  it('leaves an unpinned row on the base surface', () => {
    render(
      <ul>
        <ChatMessageRow message={message} isPinned={false} />
      </ul>,
    )
    const row = screen.getByRole('listitem')
    expect(row.className).toContain('bg-white')
    expect(screen.queryByText('Pinned')).toBeNull()
  })
})

