import { describe, expect, it } from 'vitest'
import { formatDelta, formatSplitTime } from './formatSplit'

describe('formatSplitTime', () => {
  it('pads seconds and hundredths to a fixed width', () => {
    expect(formatSplitTime(424300)).toBe('7:04.30')
  })

  it('leaves minutes unpadded past ten minutes', () => {
    expect(formatSplitTime(752090)).toBe('12:32.09')
  })
})

describe('formatDelta', () => {
  it('signs a gain and keeps two decimals', () => {
    expect(formatDelta(0.85)).toBe('+0.85')
  })

  it('keeps two decimals on a loss', () => {
    expect(formatDelta(-1.2)).toBe('-1.20')
  })
})

