import { useEffect, useState } from 'react'
import type { FrameSample } from './types'

interface DiagnosticsState {
  series: FrameSample[]
  isLoading: boolean
}

export function useIngestDiagnostics(regionId: string): DiagnosticsState {
  const [state, setState] = useState<DiagnosticsState>({ series: [], isLoading: true })

  useEffect(() => {
    setState({ series: [], isLoading: true })
    fetch(`/api/ingest/${regionId}/diagnostics`)
      .then((res) => res.json())
      .then((body: FrameSample[]) => setState({ series: body, isLoading: false }))

    const socket = new WebSocket(`wss://ingest.hexcast.dev/regions/${regionId}`)
    socket.onmessage = (event) => {
      const sample = JSON.parse(event.data) as FrameSample
      setState((prev) => ({ ...prev, series: [...prev.series, sample] }))
    }
    return () => socket.close()
  }, [regionId])

  return state
}

