/** The HTTP snapshot and the live socket can interleave; keep one entry per timestamp, oldest first. */
export function mergeFrameSamples(snapshot: FrameSample[], live: FrameSample[]): FrameSample[] {
  const byTimestamp = new Map<number, FrameSample>()
  for (const sample of [...snapshot, ...live]) {
    byTimestamp.set(sample.at, sample)
  }
  return [...byTimestamp.values()].sort((a, b) => a.at - b.at)
}

