import { renderHook, waitFor } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { useIngestDiagnostics } from './useIngestDiagnostics'

const snapshots: Array<(samples: unknown) => void> = []
const sockets: FakeSocket[] = []

class FakeSocket {
  onmessage: ((event: { data: string }) => void) | null = null
  close = vi.fn()

  constructor() {
    sockets.push(this)
  }
}

beforeEach(() => {
  snapshots.length = 0
  sockets.length = 0
  vi.stubGlobal('WebSocket', FakeSocket)
  vi.stubGlobal(
    'fetch',
    () =>
      new Promise((resolve) => {
        snapshots.push((samples) => resolve({ json: () => Promise.resolve(samples) }))
      }),
  )
})

describe('useIngestDiagnostics', () => {
  it('ignores a snapshot that resolves after the region changed', async () => {
    const { result, rerender } = renderHook(({ region }) => useIngestDiagnostics(region), {
      initialProps: { region: 'eu-frankfurt' },
    })
    rerender({ region: 'sa-saopaulo' })
    snapshots[1]([{ at: 1712, droppedFrames: 3 }])
    snapshots[0]([{ at: 1698, droppedFrames: 214 }])

    await waitFor(() => expect(result.current.isLoading).toBe(false))
    expect(result.current.series).toEqual([{ at: 1712, droppedFrames: 3 }])
  })

  it('keeps socket samples that landed while the snapshot was in flight', async () => {
    const { result } = renderHook(() => useIngestDiagnostics('us-ashburn'))
    sockets[0].onmessage?.({ data: JSON.stringify({ at: 1720, droppedFrames: 5 }) })
    snapshots[0]([{ at: 1700, droppedFrames: 1 }])

    await waitFor(() => expect(result.current.series).toHaveLength(2))
    expect(result.current.series.map((sample) => sample.at)).toEqual([1700, 1720])
  })
})

