import { useEffect, useState } from 'react'
import { clampSample } from '~/hud/clampSample'

const WINDOW_SIZE = 40

export function useLatencySamples(sessionUrl: string): number[] {
  const [samples, setSamples] = useState<number[]>([])

  useEffect(() => {
    const socket = new WebSocket(sessionUrl)
    socket.onmessage = (event) => {
      const ms = clampSample(Number(JSON.parse(event.data).inputLatencyMs))
      setSamples([...samples, ms].slice(-WINDOW_SIZE))
    }
    return () => socket.close()
  }, [sessionUrl])

  return samples
}

