import { renderHook, waitFor } from '@testing-library/react'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { useLatencySamples } from './useLatencySamples'

const sockets: FakeSocket[] = []

class FakeSocket {
  onmessage: ((event: { data: string }) => void) | null = null
  close = vi.fn()

  constructor() {
    sockets.push(this)
  }
}

function push(ms: number) {
  sockets[0].onmessage?.({ data: JSON.stringify({ inputLatencyMs: ms }) })
}

beforeEach(() => {
  sockets.length = 0
  vi.stubGlobal('WebSocket', FakeSocket)
})

describe('useLatencySamples', () => {
  it('keeps every sample the socket delivers, not just the first', async () => {
    const { result } = renderHook(() => useLatencySamples('wss://edge.framedeck.gg/s/9f21'))
    push(38)
    push(44)
    push(41)

    await waitFor(() => expect(result.current).toEqual([38, 44, 41]))
  })

  it('caps the window at 40 samples', async () => {
    const { result } = renderHook(() => useLatencySamples('wss://edge.framedeck.gg/s/9f21'))
    for (let i = 0; i < 45; i += 1) {
      push(30 + i)
    }

    await waitFor(() => expect(result.current).toHaveLength(40))
    expect(result.current[0]).toBe(35)
  })
})

