export type RoomEvent = PlaybackEvent | ChatEvent

import type { ChatEvent, PlaybackEvent, RoomEvent } from './types'
import type { RoomPlayer } from './RoomPlayer'

export function handleRoomEvent(
  event: RoomEvent,
  player: RoomPlayer,
  appendChat: (event: ChatEvent) => void,
): void {
  if (event.type === 'chat') {
    appendChat(event)
  }

  const playback = event as PlaybackEvent
  if (playback.type === 'play') {
    player.play()
  } else if (playback.type === 'pause') {
    player.pause()
  }

  player.seekTo(playback.positionSeconds)
}

