import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { ClipProgressRow } from './ClipProgressRow'
import type { RenderJob } from './types'

const job: RenderJob = {
  id: 'job-7741',
  clipTitle: 'Ranked climb, final round ace',
  status: 'rendering',
  percent: 62.4,
  updatedAt: '2026-07-24T09:14:02Z',
}

describe('ClipProgressRow', () => {
  it('shows the percent carried on the job', () => {
    render(
      <ul>
        <ClipProgressRow job={job} />
      </ul>,
    )
    expect(screen.getByText('62%')).toBeInTheDocument()
  })

  it('reports the same value to assistive tech', () => {
    render(
      <ul>
        <ClipProgressRow job={job} />
      </ul>,
    )
    expect(screen.getByRole('progressbar')).toHaveAttribute('aria-valuenow', '62')
  })

  it('renders a queued job at zero', () => {
    render(
      <ul>
        <ClipProgressRow job={{ ...job, status: 'queued', percent: 0 }} />
      </ul>,
    )
    expect(screen.getByText('0%')).toBeInTheDocument()
  })
})

