import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'

import { TurfQueue } from './TurfQueue'

function turf(id: string, completedDoors: number, totalDoors: number) {
  return { id, name: `Precinct ${id}`, completedDoors, totalDoors }
}

describe('TurfQueue', () => {
  it('drops a turf once the last door is knocked', () => {
    render(<TurfQueue canvasserName="Priya Raman" turfs={[turf('14B', 62, 62)]} />)
    expect(screen.queryByText('Precinct 14B')).not.toBeInTheDocument()
  })

  it('keeps a turf that still has a door left', () => {
    render(<TurfQueue canvasserName="Priya Raman" turfs={[turf('14B', 61, 62)]} />)
    expect(screen.getByText('Precinct 14B')).toBeInTheDocument()
  })

  it('shows the close-out state when nothing is left in the queue', () => {
    render(<TurfQueue canvasserName="Priya Raman" turfs={[turf('14B', 62, 62)]} />)
    expect(screen.getByText(/Every door on your packet has been knocked/)).toBeInTheDocument()
    expect(screen.getByRole('link', { name: 'Close out my shift' })).toBeInTheDocument()
  })
})

