import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { fetchShelters } from '../../api/shelters'
import { ShelterSearch } from './ShelterSearch'

vi.mock('../../api/shelters', () => ({ fetchShelters: vi.fn() }))

const mockedFetch = vi.mocked(fetchShelters)

afterEach(() => {
  mockedFetch.mockReset()
})

describe('ShelterSearch', () => {
  it('ignores a slow first response that lands after a newer one', async () => {
    const bayou = { id: 'shl-12', name: 'Bayou Road Middle School', cots: 180, intakeOpen: true }
    mockedFetch
      .mockImplementationOnce(() => new Promise((resolve) => setTimeout(() => resolve([]), 40)))
      .mockResolvedValueOnce([bayou])

    render(<ShelterSearch countyName="Terrebonne Parish" />)
    await userEvent.type(screen.getByLabelText('Search shelters in Terrebonne Parish'), 'b')

    await waitFor(() => expect(screen.getByText('Bayou Road Middle School')).toBeInTheDocument())
    await new Promise((resolve) => setTimeout(resolve, 60))
    expect(screen.getByText('Bayou Road Middle School')).toBeInTheDocument()
  })

  it('offers a way back when a query matches nothing', async () => {
    mockedFetch.mockResolvedValue([])
    render(<ShelterSearch countyName="Terrebonne Parish" />)
    await userEvent.type(screen.getByLabelText('Search shelters in Terrebonne Parish'), 'q')

    await waitFor(() => expect(screen.getByText(/No shelters match/)).toBeInTheDocument())
    expect(screen.getByRole('button', { name: 'Clear the search' })).toBeInTheDocument()
  })
})

