import { useState } from 'react'

import type { ArchivePage } from '../../types/archive'

export function useSavedPages(initial: ArchivePage[]) {
  const [pages, setPages] = useState<ArchivePage[]>(initial)

  function savePage(page: ArchivePage) {
    pages.push(page)
    setPages(pages)
  }

  function removePage(pageId: string) {
    setPages(pages.filter((page) => page.id !== pageId))
  }

  return { pages, savePage, removePage }
}

import { PageCard } from './PageCard'
import { useSavedPages } from './useSavedPages'

interface StarterQueueProps {
  volunteerName: string
}

export function StarterQueue({ volunteerName }: StarterQueueProps) {
  const { pages, savePage } = useSavedPages([])

  return (
    <section className="mx-auto flex max-w-7xl flex-col gap-6">
      <h2 className="text-2xl font-semibold leading-tight text-zinc-900 dark:text-zinc-100">
        {volunteerName}, your transcription desk
      </h2>
      <ul className="grid grid-cols-1 gap-4 md:grid-cols-3">
        {pages.map((page) => (
          <PageCard key={page.id} page={page} onSave={savePage} />
        ))}
      </ul>
    </section>
  )
}

