import { act, render, renderHook, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'

import { StarterQueue } from './StarterQueue'
import { useSavedPages } from './useSavedPages'

const ledgerPage = {
  id: 'apg-1874-0113',
  title: 'Ledger of the Ninth Ward relief fund, January 1874',
  scanUrl: '/scans/1874-0113.jpg',
}

describe('StarterQueue', () => {
  it('shows the first-run desk copy when nothing is saved', () => {
    render(<StarterQueue volunteerName="Dolores Achebe" />)
    expect(screen.getByText('You have not picked up a page yet')).toBeInTheDocument()
    expect(screen.getByRole('link', { name: 'Browse the catalog' })).toBeInTheDocument()
  })
})

describe('useSavedPages', () => {
  it('replaces the array instead of mutating it so the desk re-renders', () => {
    const { result } = renderHook(() => useSavedPages([]))
    const before = result.current.pages
    act(() => result.current.savePage(ledgerPage))
    expect(result.current.pages).not.toBe(before)
    expect(result.current.pages).toHaveLength(1)
  })

  it('does not stack the same page twice', () => {
    const { result } = renderHook(() => useSavedPages([]))
    act(() => result.current.savePage(ledgerPage))
    act(() => result.current.savePage(ledgerPage))
    expect(result.current.pages).toHaveLength(1)
  })
})
